[1634] = "原始标识符",
-- 8bec02bf English: Destination identifier
-- Context: Label and edit-box title in the function bundle review: the identifier the entry will
--     get after import.
[1635] = "目标标识符",
-- 32e8d276 English: Callback
-- Context: Label of the dropdown in the function-source review dialog that selects which callback
--     (a part of the code) to view.
[1636] = "回调",
-- 222b67d3 English: Include custom function dependencies
[1637] = "包含自定义函数依赖项",
-- df750ab9 English: Review import
-- Context: Button in the function bundle import dialog: checks the pasted bundle and lists what
--     would change, without applying it.
[1638] = "检查导入",
-- 454d876b English: Apply import
-- Context: Button in the function bundle review dialog: carries out the import (verb).
[1639] = "应用导入",
-- b7143073 English: Function dependency bundle
-- Context: Title of the dialog for exporting/importing a bundle of functions together with the
--     functions they depend on.
[1640] = "函数依赖包",
-- 44fc47f3 English: Review the complete bundle before applying an import. Imported Lua can execute
--     when registered; only apply code you trust.
[1641] = "应用导入前请检查完整的依赖包。导入的 Lua 在注册时可能会执行；只应用你信任的代码。",
-- b5ca2246 English: Review each original name, destination and dependency below. Apply import saves
--     the complete reviewed bundle.
[1642] = "检查下方每个原始名称、目标和依赖项。“应用导入”会保存经过检查的完整依赖包。",
-- 0f2dd42f English: Conflict action
-- Context: Label of the dropdown in the function bundle review that chooses what to do when an
--     identifier already exists (Reuse, Replace, ...).
[1643] = "冲突处理方式",
-- 4e81098c English: Imported name
-- Context: Label of the edit box in the function bundle review holding the display name the
--     imported entry will have.
[1644] = "导入的名称",
-- 8e818b1f English: Existing dependents
-- Context: Label in the function bundle review, followed by a list: the existing functions or
--     conditions that already use the one being replaced.
[1645] = "现有的依赖方",
-- 75c417a1 English: This imported definition is disabled. Its dependents remain unavailable.
[1646] = "此导入的定义已禁用。依赖它的项目仍不可用。",
-- 2643e762 English: Required functions
-- Context: Heading in the function bundle review for the functions the import depends on.
[1647] = "所需函数",
-- 103c8bbb English: Paste a bundle above, then review its original names, destinations and required
--     functions.
[1648] = "在上方粘贴一个依赖包，然后检查其原始名称、目标和所需函数。",
-- 7f12e5bc English: Filter Built In or Custom helpers and search their names, identifiers or
--     descriptions. Packaged helpers show read-only source and typed documentation. Duplicate
--     creates an editable copy with a new stable identifier. Argument and return rows document the
--     Lua signature.
[1649] = "筛选内置或自定义辅助函数，并搜索其名称、标识符或描述。内置辅助函数显示只读源码和带类型的文档。“复制”会创建一个带有新的稳定标识符的可编辑副本。参数行和返回值行记录了 Lua 函数签名。",
-- 812ccde3 English: Expand Function bindings to add explicit helper aliases and choose their
--     targets. Changing an alias does not rewrite your Lua body. Missing, disabled or invalid
--     dependencies keep their dependents unavailable until repaired.
[1650] = "展开“函数绑定”可添加显式的辅助函数别名并选择其目标。更改别名不会重写你的 Lua 函数体。缺失、已禁用或无效的依赖项会使依赖它们的项目在修复前保持不可用。",
-- 9d60841e English: Check
[1651] = "检查",
-- b64ac05f English: Live
-- Context: Checkbox in the condition test dialog: keeps re-running the test repeatedly while the
--     dialog stays open (live updating).
[1652] = "实时",
-- 324b134f English: Preview
-- Context: Title of a help topic: the preview of an effect in the effect editor, and the preview
--     window's sample in General settings help. A noun.
[1653] = "预览",
-- a31ec5d7 English: The preview failed. Use /rm errors for details.
[1654] = "预览失败。详情请使用 /rm errors。",
-- 1c103e84 English: Test values were not saved because they are not bounded plain data.
[1655] = "测试值未保存，因为它们不是有限的纯数据。",
-- c1ab4306 English: Condition check
[1656] = "条件检查",
-- 0fa00491 English: Fields UI preview
-- Context: Title of the condition test dialog when it is opened from the developer debug tools to
--     preview a condition's fields user interface.
[1657] = "字段界面预览",
-- 367bba74 English: Help preview
-- Context: Title of the condition test dialog when it is opened from the developer debug tools to
--     preview a condition's help page.
[1658] = "帮助预览",
-- 59e490f3 English: Edit detached test values below. Check validates them before evaluating. Live
--     is opt-in; test values are saved separately from the condition source.
[1659] = "在下方编辑独立的测试值。“检查”会先验证再评估。“实时”需手动开启；测试值与条件源码分开保存。",
-- 8b1c0e1c English: Preview runs only this callback with detached sample values. It does not save
--     or register the condition.
[1660] = "预览只会使用独立的示例值运行此回调。它不会保存或注册条件。",
-- 75d9602c English: Complete the source fields before checking.
[1661] = "检查前请先完成源码字段。",
-- 00454de7 English: Check could not compile the current source. Fix the source before checking
--     again.
[1662] = "“检查”无法编译当前源码。请修复源码后再检查。",
-- 6a255986 English: Skipped: invalid test values
[1663] = "已跳过：测试值无效",
-- 4607aa3d English: Validation: %s
-- %s #1: %s #1: the validation result, one of "Passed", "Failed" or "Unavailable" (translated), e.g. "Passed"
[1664] = "验证：%s",
-- 436fe71b English: Passed
-- Context: Result word in the condition test dialog: the test passed.
[1665] = "通过",
-- 4c852a7e English: Evaluation: %s
-- %s #1: %s #1: the result of the test evaluation, a short phrase such as "True", "False" or "Skipped: invalid test values" (translated), e.g. "True"
[1666] = "评估：%s",
-- 55a7b6a1 English: Fields UI and Help offer an explicit Preview of the current callback. Preview
--     uses detached sample values and the normal field or help renderer. It does not save,
--     register, validate or evaluate the condition. Closing it releases its controls and returns to
--     the source draft. Check syntax never runs a callback.
[1667] = "“字段界面”和“帮助”提供当前回调的显式“预览”。预览使用独立的示例值以及正常的字段或帮助渲染器。它不会保存、注册、验证或评估条件。关闭后会释放其控件并返回源码草稿。“检查语法”从不运行回调。",
-- 106d8f1b English: Evaluate and Validate offer Check with the same Fields UI and detached sample
--     values. Check runs validation first, then evaluates only valid values. Results show true,
--     false or an unavailable reason. Live is opt-in and checks at most twice per second while this
--     panel is shown; closing stops it. Test values are saved separately and never enter condition
--     exports or rotation edits. Source changes run no callbacks unless you check again or enable
--     Live.
[1668] = "“评估”和“验证”提供“检查”，使用相同的字段界面和独立的示例值。“检查”会先进行验证，然后只评估有效的值。结果显示为真、假或不可用的原因。“实时”需手动开启，在此面板显示期间每秒最多检查两次；关闭面板即停止。测试值单独保存，永远不会进入条件导出或循环编辑。除非你再次检查或启用“实时”，否则源码更改不会运行任何回调。",
-- 5d331ffe English: Functions reference
-- Context: Title of a section in the custom condition editor's help: the page that documents public
--     helper functions (noun phrase).
[1669] = "函数参考",
-- 64334745 English: The Functions page documents public helpers and their typed arguments, return
--     values and source. Context completion and hover use that reference; Ctrl-click a known helper
--     to open its source. Use explicit binding aliases for reusable custom helpers.
[1670] = "“函数”页面记录了公共辅助函数及其带类型的参数、返回值和源码。上下文补全和悬停提示会使用这些参考；按住 Ctrl 点击已知的辅助函数可打开其源码。对可复用的自定义辅助函数，请使用显式的绑定别名。",
-- 8f344bfe English: The imported definition type does not match this editor.
[1671] = "导入的定义类型与此编辑器不匹配。",
-- 91fe2974 English: Test values changed. Check again to refresh the result.
[1672] = "测试值已更改。请再次检查以刷新结果。",
-- 4087dcf1 English: Complete the highlighted test inputs before checking.
[1673] = "检查前请先完成高亮标出的测试输入。",
-- 532eaabd English: Test
-- Context: Button in the custom condition editor, and the dialog subtitle: runs the condition once
--     with sample input (verb).
[1674] = "测试",
-- e031e0df English: Run test
-- Context: Button and tooltip in the Lua workbench query panel: runs the entered code once with the
--     test arguments (verb phrase).
[1675] = "运行测试",
-- 312acdf1 English: Test condition
-- Context: Title of the dialog that tries a custom condition with sample values (verb phrase used
--     as a title).
[1676] = "测试条件",
-- 34fb96f5 English: Debugger output
[1677] = "调试器输出",
-- e376955f English: Set test values in Test before debugging Evaluate.
[1678] = "调试“评估”前，请先在“测试”中设置测试值。",
-- 427ea36c English: Debugger output uses a detached sample and the normal field or help container.
[1679] = "调试器输出使用独立的示例以及正常的字段或帮助容器。",
-- af624aba English: Choose test values in Fields UI, then Run test to validate and evaluate. Help
--     is shown below the fields. Opening Test does not evaluate defaults. Live is opt-in.
[1680] = "在字段界面中选择测试值，然后点击“运行测试”进行验证和评估。帮助显示在字段下方。打开“测试”不会评估默认值。“实时”需手动开启。",
-- fba588f1 English: Test opens one condition-level dialog from any callback tab. It renders Fields
--     UI and Help together with detached values. Choose the fields and Run test to validate, then
--     evaluate only valid values. Opening the dialog does not evaluate defaults. Live is opt-in and
--     stops when the dialog closes. Committed test values are available to the debugger and stay
--     separate from source, exports and rotation edits. Check syntax never runs a callback.
[1681] = "“测试”会从任一回调标签页打开一个条件级对话框。它会结合独立的测试值同时渲染字段界面和帮助。选择字段并点击“运行测试”进行验证，然后只评估有效的值。打开对话框不会评估默认值。“实时”需手动开启，并在对话框关闭时停止。已提交的测试值可供调试器使用，并与源码、导出内容和循环编辑相互独立。“检查语法”从不运行回调。",
-- deba1c35 English: Nullable
-- Context: Checkbox in the argument/return type editor of the function source pane: the value may
--     also be nil (empty).
[1682] = "可为空",
-- fbf338e4 English: Add return value
[1683] = "添加返回值",
-- c75ed23e English: Lua returns multiple values in order. Each row documents one result.
[1684] = "Lua 会按顺序返回多个值。每一行记录一个结果。",
-- f968686c English: Expand code editor
-- Context: Tooltip of the button on the code editor corner in the function source pane: enlarges
--     the editor to fill the pane (verb phrase).
[1685] = "展开代码编辑器",
-- cc81db61 English: Restore code editor
-- Context: Tooltip of the same button after the editor is enlarged: shrinks it back to its normal
--     size (verb phrase).
[1686] = "还原代码编辑器",
-- cb050073 English: Choose a source helper and the local name used to call it in this Lua body.
--     Renaming the local name does not rewrite code. Source modules distinguish helpers with the
--     same name.
[1687] = "选择一个源辅助函数，以及在此 Lua 函数体中调用它时使用的本地名称。重命名本地名称不会重写代码。源模块用于区分同名的辅助函数。",
-- cfaec007 English: Local name in code
[1688] = "代码中的本地名称",
-- d076565e English: Source helper
-- Context: Column caption in the function bindings table: the existing function the alias points
--     to.
[1689] = "源辅助函数",
-- b49f05b5 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. Names suggest the local binding used to call them; registry identifiers stay
--     stable.
[1690] = "函数名称使用字母、数字和下划线，并以字母或下划线开头。名称会作为调用它们时所用本地绑定的建议；注册表标识符保持稳定。",
-- b545dd16 English: This cannot be undone.
[1691] = "此操作无法撤销。",
-- f07f87d9 English: Delete this announcement?
[1692] = "删除此通报？",
-- da985348 English: Type: %s
-- %s #1: %s #1: the Lua type name of the symbol, e.g. "number" or "string"
[1693] = "类型：%s",
-- 78a0b485 English: Supported unit-token to localized unit-name lookup. Use value.unit as a key;
--     for example addon.units[value.unit]. Available tokens vary by client.
[1694] = "受支持的单位标识到本地化单位名称的查找表。以 value.unit 作为键；例如 addon.units[value.unit]。可用的标识因客户端而异。",
-- b2a921f3 English: Supported unit-token to localized possessive unit-name lookup, such as your
--     target.
[1695] = "受支持的单位标识到本地化所有格单位名称（例如“你的目标的”）的查找表。",
-- 7e1dc663 English: Rotation Master client compatibility adapter. Its methods return ordinary
--     readable results or nil with a reason when an observation is unavailable. Use a colon call,
--     or pass addon.Platform explicitly as self with a dot reference.
[1696] = "Rotation Master 客户端兼容性适配器。其方法返回普通的可读结果；当观测不可用时返回 nil 及原因。请使用冒号调用，或在点号引用时显式将 addon.Platform 作为 self 传入。",
-- bbc0cdbf English: Rotation Master spell catalog for resolving client-specific spell IDs, ranks,
--     names, icons and links.
[1697] = "Rotation Master 法术目录，用于解析因客户端而异的法术 ID、等级、名称、图标和链接。",
-- 18123a69 English: Utility functions explicitly bound to this condition or function. Choose a
--     completion to bind an available custom function before inserting its reference.
[1698] = "显式绑定到此条件或函数的工具函数。在插入其引用前，选择一个补全项以绑定可用的自定义函数。",
-- 16356339 English: Rotation Master custom function
[1699] = "Rotation Master 自定义函数",
-- 902c5c44 English: Rotation Master built-in function
[1700] = "Rotation Master 内置函数",
-- 0443c4a6 English: Rotation Master value
-- Context: Heading in the Lua editor's hover text for a symbol that is a plain value provided by
--     Rotation Master (not a function); the alternatives are 'Rotation Master custom function' and
--     'Rotation Master built-in function'.
[1701] = "Rotation Master 值",
-- 1a845fe0 English: Global function (documentation unavailable on this client)
[1702] = "全局函数（此客户端上没有文档）",
-- 6912e131 English: This client does not provide signature documentation for this function. No
--     arguments or return types have been inferred.
[1703] = "此客户端未提供此函数的签名文档。未推断任何参数或返回类型。",
-- 90092e5f English: Invoke
[1704] = "调用",
-- cb214676 English: Functions are shared across profiles after Apply. Call custom utilities as
--     functions.name(...); accepting completion adds the dependency binding. Typed calls need a
--     binding under Function bindings. Built In examples show dot or colon explicitly.
[1705] = "函数在应用后会在所有配置文件间共享。以 functions.name(...) 调用自定义工具函数；接受自动补全会添加依赖绑定。带类型的调用需要在“函数绑定”下有一个绑定。内置示例会显式使用点号或冒号。",
-- d03262ba English: Show line numbers
-- Context: Checkbox in Integrations settings (Lua editor section): shows line numbers in the Lua
--     code editors; also a help topic title.
[1706] = "显示行号",
-- f12fff00 English: Line-number visibility applies to every condition and function code editor.
[1707] = "行号显示设置适用于每个条件和函数的代码编辑器。",
-- 596578e6 English: Call a saved custom utility as functions.name(...). Accepting a completion
--     attaches its stable dependency binding; for a typed call, choose its helper under Function
--     bindings. Existing direct aliases still work. The Invoke example shows required addon dot or
--     colon syntax for Built In functions. Renaming an alias does not rewrite source. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1708] = "以 functions.name(...) 调用已保存的自定义工具函数。接受自动补全会附加其稳定的依赖绑定；对于带类型的调用，请在“函数绑定”下选择其辅助函数。现有的直接别名仍可使用。“调用”示例展示了内置函数所需的 addon 点号或冒号语法。重命名别名不会重写源码。缺失、已禁用或无效的依赖项会使使用它们的项目保持不可用。",
-- 38416c88 English: Choose the editor for custom Lua conditions and functions. Show line numbers
--     applies across code editors. Built In syntax highlighting and Plain text work without another
--     addon. Automatic selects a connected provider or falls back safely. Apply saves settings;
--     editor changes take effect on reopening, and line-number visibility updates open editors.
--     LuaWorkbench and WowLua loading status is shown separately from integration availability.
[1709] = "选择自定义 Lua 条件和函数所用的编辑器。“显示行号”适用于所有代码编辑器。“内置语法高亮”和“纯文本”无需其他插件即可使用。“自动”会选择一个已连接的提供者，或安全地回退。“应用”会保存设置；编辑器的更改在重新打开时生效，行号显示会更新已打开的编辑器。LuaWorkbench 和 WowLua 的加载状态与集成可用性分开显示。",
-- 50c3cb6e English: All namespaces
-- Context: First entry of the namespace filter dropdown on the Functions page: show functions from
--     every namespace.
[1710] = "所有命名空间",
-- 5605815a English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self: the Invoke example includes a method receiver explicitly, and
--     Existing API preserves its original dot or colon spelling. Existing aliases still work.
--     Renaming a function or namespace does not rewrite existing code or bindings. Missing,
--     disabled or invalid dependencies keep consumers unavailable.
[1711] = "以 namespace.name(...) 调用工具函数。内置命名空间与源文件对应；自定义函数自行选择其命名空间。接受自动补全会附加其稳定的依赖绑定；对于带类型的调用，请在“函数绑定”下添加其完整限定名。命名空间不提供 self：“调用”示例会显式包含方法接收者，“现有 API”保留其原有的点号或冒号写法。现有别名仍可使用。重命名函数或命名空间不会重写现有代码或绑定。缺失、已禁用或无效的依赖项会使使用它们的项目保持不可用。",
-- 66506282 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. Namespaces are private to this callback. Renaming a binding does not rewrite
--     code.
[1712] = "在此 Lua 函数体中选择一个源辅助函数及其名称，例如 custom.ready 或 utils.getCached。命名空间是此回调私有的。重命名绑定不会重写代码。",
-- 5226404c English: Existing API
[1713] = "现有 API",
-- e572edc2 English: Name in code
-- Context: Column caption in the function bindings table and tooltip of the alias field: the name a
--     binding is called inside the Lua code.
[1714] = "代码中的名称",
-- c4e4e7ab English: Namespace
-- Context: Label of the namespace box in the function source pane and a help section title: the
--     dotted group name under which a function is listed.
[1715] = "命名空间",
-- c6d86222 English: Namespaces group functions; they do not supply a receiver. Accept a completion
--     to bind the shown dotted call. For a typed call, add the same qualified name under Function
--     bindings. Method examples include the required receiver explicitly. Functions are shared
--     across profiles after Apply.
[1716] = "命名空间用于对函数分组；它们不提供接收者。接受自动补全即可绑定所显示的点号调用。对于带类型的调用，请在“函数绑定”下添加相同的完整限定名。方法示例会显式包含所需的接收者。函数在应用后会在所有配置文件间共享。",
-- 76209725 English: Private utility-function namespace. It contains only explicit bindings for this
--     callback.
[1717] = "私有的工具函数命名空间。它只包含此回调的显式绑定。",
-- 481da3a7 English: Argument
-- Context: Row title and add-button text in the function source pane: one function argument (noun).
--     The same place has "Return".
[1718] = "参数",
-- e0836fce English: Bindings (%d)
-- %d #1: %d #1: the number of function bindings, e.g. 3
[1719] = "绑定（%d）",
-- 6ecb5a70 English: Call a utility as namespace.name(...). Built In namespaces follow source files;
--     custom functions choose their Namespace. Accepting a completion attaches its stable
--     dependency binding; for a typed call, add its qualified name under Function bindings.
--     Namespaces do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is Lua shorthand for object.method(object, x). Existing addon APIs remain
--     compatible with saved definitions. Existing aliases still work. Renaming a function or
--     namespace does not rewrite existing code or bindings. Missing, disabled or invalid
--     dependencies keep consumers unavailable.
[1720] = "以 namespace.name(...) 调用工具函数。内置命名空间与源文件对应；自定义函数自行选择其命名空间。接受自动补全会附加其稳定的依赖绑定；对于带类型的调用，请在“函数绑定”下添加其完整限定名。命名空间不提供 self。在命名空间的点号调用中请显式传入方法接收者；object:method(x) 是 Lua 中 object.method(object, x) 的简写。现有插件 API 与已保存的定义保持兼容。现有别名仍可使用。重命名函数或命名空间不会重写现有代码或绑定。缺失、已禁用或无效的依赖项会使使用它们的项目保持不可用。",
-- d35a9985 English: Changing argument or return order can break existing callers. Rotation Master
--     will not rewrite their Lua code. Continue?
[1721] = "更改参数或返回值的顺序可能会破坏现有的调用方。Rotation Master 不会重写它们的 Lua 代码。是否继续？",
-- 2199cecc English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Reordering a saved function warns because positional callers may
--     need changes; RM does not rewrite call sites.
[1722] = "点击“参数”或“返回值”标题可将其折叠或展开。“+ 参数”和“+ 返回值”在点击时追加到末尾，拖动时则插入到高亮显示的空隙。拖动某一行或使用“上移 / 下移”来重新排序；按住 Ctrl 拖动会带上后续的行。垃圾桶会移除一行。“类型”和“可为空”记录可接受的值；“描述”说明每个输入或结果。Lua 可以按顺序返回多个结果。对已保存的函数重新排序时会发出警告，因为按位置调用的调用方可能需要修改；RM 不会重写调用处。",
-- 6b0143d0 English: Return
-- Context: Row title and add-button text in the function source pane: one function return value
--     (noun). The same place has "Argument".
[1723] = "返回值",
-- 2584fdfb English: Changing argument order can break existing callers. Rotation Master will not
--     rewrite their Lua code. Continue?
[1724] = "更改参数顺序可能会破坏现有的调用方。Rotation Master 不会重写它们的 Lua 代码。是否继续？",
-- 79fbb27b English: Changing return documentation order does not rewrite return statements or
--     existing callers. Review the Lua body and callers for the new order. Continue?
[1725] = "更改返回值文档的顺序不会重写 return 语句或现有的调用方。请按新的顺序检查 Lua 函数体和调用方。是否继续？",
-- 2266dd0b English: Card controls
-- Context: Heading of a section in the argument editor help: explains the controls on an argument's
--     card.
[1726] = "卡片控件",
-- 1f03f52f English: Describe this value for function documentation, completion and hover help.
--     Changes remain in the draft until Apply.
[1727] = "描述此值，用于函数文档、自动补全和悬停帮助。更改会保留在草稿中，直到点击“应用”。",
-- 9513dcfb English: Drag a card to reorder arguments; Ctrl-drag includes following arguments. Up
--     and down move one position. Duplicate copies the argument with a unique name; the trash can
--     removes it. Reordering a saved function requires confirmation because existing callers are
--     not rewritten.
[1728] = "拖动卡片可重新排列参数；按住 Ctrl 拖动会包括后续参数。上下箭头每次移动一个位置。“复制”会以唯一的名称复制参数；垃圾桶会移除它。对已保存的函数重新排序需要确认，因为现有的调用方不会被重写。",
-- 33f24b5d English: Drag a card to reorder return documentation; Ctrl-drag includes following
--     returns. Up and down move one position. Duplicate copies the documented return value; the
--     trash can removes it. Return order in this list does not rewrite return statements or
--     callers.
[1729] = "拖动卡片可重新排列返回值文档；按住 Ctrl 拖动会包括后续返回值。上下箭头每次移动一个位置。“复制”会复制所记录的返回值；垃圾桶会移除它。此列表中的返回值顺序不会重写 return 语句或调用方。",
-- 74057930 English: Rendered output appears here when the callback runs or steps through widget
--     creation.
[1730] = "当回调运行或单步执行控件创建时，渲染的输出会显示在这里。",
-- 47b50257 English: Set values in Test before running or debugging this condition.
[1731] = "运行或调试此条件前，请先在“测试”中设置数值。",
-- 96aa8cc3 English: The argument name is the local parameter available in the Lua body. Use a valid
--     Lua identifier. Renaming this documentation does not rewrite references in the code.
[1732] = "参数名称是 Lua 函数体中可用的本地形参。请使用有效的 Lua 标识符。重命名此文档不会重写代码中的引用。",
-- 438e9a47 English: Type and Nullable describe the values accepted or returned by this function.
--     They document the contract; they do not rewrite or validate values in the Lua body.
[1733] = "“类型”和“可为空”描述此函数接受或返回的值。它们记录的是约定；不会重写或验证 Lua 函数体中的值。",
-- 42e8bcf1 English: Debuffs
-- Context: Condition category in the icon picker's category list: debuff-related icons (plural
--     noun).
[1734] = "减益效果",
-- e89b30aa English: Resources
-- Context: Condition category in the icon picker's category list: resources such as mana and rage.
[1735] = "资源",
-- 8f0d1b30 English: Pet
-- Context: Condition category in the icon picker's category list: pet-related icons.
[1736] = "宠物",
-- 7c400199 English: Logic
-- Context: Condition category in the icon picker's category list: logical operators (and/or/not).
[1737] = "逻辑",
-- 9e471951 English: Environment
-- Context: Condition category in the icon picker's category list: environment (weather, zone ...).
[1738] = "环境",
-- 33b93476 English: Time
-- Context: Condition category in the icon picker's category list: time-related icons.
[1739] = "时间",
-- 66f9cfa2 English: Spell Auto-Repeat Active
-- Context: Condition type title: true when the spell is set to auto-repeat (e.g. Auto Shot, wand).
--     Also an icon name in the icon picker.
[1740] = "法术自动重复中",
-- 01059048 English: Retribution (Wowhead & simulator)
[1741] = "惩戒（Wowhead & 模拟器）",
-- 6fc82107 English: Melee Retribution from level 1 to 70, and the default for any Paladin no other
--     premade fits. Opens each target with Judgement of Wisdom (low mana) or the Crusader, keeps
--     your best seal up (Blood or Martyr, Command, then Righteousness), Crusader Strike, judges
--     only Righteousness, Blood or Martyr (or Command on a stunned target), Exorcism on Undead and
--     Demons, Consecration for three or more enemies with mana to spare. Hammer of Wrath is left to
--     you (Wowhead uses it only on fleeing targets). Reminders: Sanctity, Retribution or Devotion
--     Aura, a Blessing on yourself, a heal after the fight, Avenging Wrath. Seal twisting is a
--     separate premade.
[1742] = "惩戒近战，适用于 1 至 70 级，也是没有其他内置循环适用时所有圣骑士的默认循环。对每个目标以智慧审判（法力值低时）或十字军审判开场，保持你最好的圣印（鲜血圣印或殉难圣印、命令圣印，其次是正义圣印），使用十字军打击，只审判正义圣印、鲜血圣印或殉难圣印（对昏迷的目标则审判命令圣印），对亡灵和恶魔使用驱邪术，三个或更多敌人且法力充足时使用奉献。愤怒之锤由你决定（Wowhead 仅对逃跑的目标使用）。提醒：圣洁光环、惩罚光环或虔诚光环、对自己施放祝福、战斗后治疗、复仇之怒。圣印轮换是单独的内置循环。",
-- 89f00a09 English: Retribution (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     The Burning Crusade Classic (variant key: Retribution / IcyVeins). Names in parentheses
--     (guide or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics,
--     Warcraft Tavern) are proper names and stay unchanged.
[1743] = "惩戒（Icy Veins）",
-- c68e9ea0 English: Icy Veins' Retribution, an alternative to the recommended Wowhead Retribution
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader once per target, Seal of Righteousness (Command only with a slow weapon, Blood
--     or Martyr once learned), Crusader Strike, Hammer of Wrath and Judgement on cooldown,
--     Consecration on two or more enemies, Exorcism on Undead and Demons, and Holy Shock for Holy
--     levelers. Same reminders as the Wowhead variant.
[1744] = "Icy Veins 的惩戒，是推荐的 Wowhead 惩戒内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。每个目标施放一次十字军审判，正义圣印（仅在使用慢速武器时用命令圣印，学会后用鲜血圣印或殉难圣印），十字军打击、愤怒之锤和审判冷却完毕即用，两个或更多敌人时使用奉献，对亡灵和恶魔使用驱邪术，神圣系升级者使用神圣震击。提醒与 Wowhead 版本相同。",
-- 85d846bd English: Retribution seal twisting
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     The Burning Crusade Classic (variant key: Retribution / Twist).
[1745] = "惩戒圣印轮换",
-- 34a6a34f English: Off by default; enable it if you twist seals (level 64+, Seal of Command and
--     Blood or Martyr). Opens with Judgement of the Crusader, then each swing puts up Seal of
--     Command (rank 1) early and switches to Blood or Martyr in the last 0.4 seconds, Crusader
--     Strike between twists, judges only Blood or Martyr, Exorcism and Consecration only as
--     fillers, and rolls Blood without twisting below 12% mana. Needs a reliable swing timer;
--     latency is not accounted for.
[1746] = "默认关闭；如果你会进行圣印轮换（64 级以上，拥有命令圣印和鲜血圣印或殉难圣印），请启用它。以十字军审判开场，之后每次挥击都会提前施放命令圣印（等级 1），并在最后 0.4 秒切换到鲜血圣印或殉难圣印，两次轮换之间使用十字军打击，只审判鲜血圣印或殉难圣印，驱邪术和奉献仅作为填充，法力值低于 12% 时不再轮换，只保持鲜血圣印。需要可靠的攻击计时器；未考虑延迟。",
-- b9e3d93c English: Protection (Wowhead & simulator)
[1747] = "防护（Wowhead & 模拟器）",
-- c9c2efbf English: Tanking for the Protection tree or any Paladin with Righteous Fury on. Pulls
--     with Holy Shield, Avenger's Shield and Judgement; against a crushing target (world boss or
--     three or more levels above you) Holy Shield comes first; then Consecration, Exorcism on
--     Undead and Demons, Judgement, Holy Shield, Holy Wrath on undead packs, Avenger's Shield
--     except on crushing targets. Seal of Wisdom on packs when mana is short, Righteousness
--     otherwise. Reminders: Righteous Fury, Devotion Aura, Sanctuary (or Kings, or Wisdom),
--     Avenging Wrath, Lay on Hands. Taunts and target swaps stay with you.
[1748] = "防护天赋树或任何开启正义之怒的圣骑士的坦克循环。以神圣之盾、复仇者之盾和审判拉怪；面对碾压目标（世界首领或比你高三级及以上）时先上神圣之盾；然后是奉献、对亡灵和恶魔使用驱邪术、审判、神圣之盾、对亡灵怪群使用神圣愤怒，除碾压目标外使用复仇者之盾。法力值不足时对怪群使用智慧圣印，否则使用正义圣印。提醒：正义之怒、虔诚光环、庇护祝福（或王者祝福、智慧祝福）、复仇之怒、圣疗术。嘲讽和切换目标由你自己掌控。",
-- 80b938a1 English: Protection (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Paladin,
--     The Burning Crusade Classic (variant key: Protection / IcyVeins). Names in parentheses (guide
--     or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1749] = "防护（Icy Veins）",
-- 3ae9045e English: Icy Veins' tanking, an alternative to the recommended Wowhead Protection
--     premade, off by default: enable it and disable that one, or raise its priority. Judgement of
--     the Crusader when nobody keeps it up, Righteousness (Wisdom on packs), Consecration as the
--     main threat, Judgement, Holy Shield, then Avenger's Shield and Hammer of Wrath on cooldown.
--     Same reminders as the Wowhead variant without Avenging Wrath.
[1750] = "Icy Veins 的坦克循环，是推荐的 Wowhead 防护内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。没人维持十字军审判时施放它，正义圣印（怪群时用智慧圣印），奉献作为主要仇恨来源，审判、神圣之盾，然后复仇者之盾和愤怒之锤冷却完毕即用。提醒与 Wowhead 版本相同，但不含复仇之怒。",
-- 9d88b75a English: Holy (Icy Veins & Wowhead)
[1751] = "神圣（Icy Veins & Wowhead）",
-- 879586c5 English: Healing for a Holy Paladin in a group, on your friendly target: Lay on Hands or
--     Holy Shock for a dying target, Cleanse (Purify before 42), Holy Shock while moving, Holy
--     Light for heavy damage, rank-5 Holy Light to keep Light's Grace up, Flash of Light otherwise.
--     With a hostile target it keeps Judgement of Wisdom up. Reminders: Concentration Aura,
--     Blessing of Wisdom, Divine Illumination and Divine Favor. A soloing Holy Paladin gets a
--     Retribution premade instead.
[1752] = "神圣圣骑士在队伍中的治疗，作用于你的友方目标：目标濒死时使用圣疗术或神圣震击，清洁术（42 级前为纯净术），移动时使用神圣震击，承受大量伤害时使用圣光术，用 5 级圣光术保持圣光之赐，否则使用圣光闪现。目标为敌对时保持智慧审判。提醒：专注光环、智慧祝福、神启和神恩术。单刷的神圣圣骑士会改用惩戒内置循环。",
-- 2261d994 English: Holy (Wowhead tank healing)
[1753] = "神圣（Wowhead 坦克治疗）",
-- 63b194ff English: Wowhead's raid tank healing, an alternative to the recommended Holy premade,
--     off by default: enable it and disable that one, or raise its priority. Holy Light whenever
--     your target is missing a tenth of their health, Flash of Light only for small deficits, with
--     the same emergencies, cleansing, Judgement and reminders as the blended Holy premade.
[1754] = "Wowhead 的团队坦克治疗，是推荐的神圣内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。只要目标损失十分之一的生命值就使用圣光术，仅在缺口较小时使用圣光闪现；紧急处理、驱散、审判和提醒与综合版神圣内置循环相同。",
-- ffb13c96 English: Ranged DPS (simulator)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Hunter,
--     The Burning Crusade Classic (variant key: Ranged / simulator). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1755] = "远程 DPS（模拟器）",
-- 2b43c4a1 English: Levels 1–70, every spec. Pulls with Hunter's Mark, Aimed Shot and Auto Shot,
--     keeps Auto Shot running and uses melee strikes when a target reaches you. Before Steady Shot
--     it keeps your Serpent Sting up and spends mana on Aimed, Multi and Arcane Shot only while you
--     have plenty. From level 62: Multi-Shot when ready, Steady Shot straight after each Auto Shot,
--     Arcane Shot to fill the gap, Serpent Sting when solo. With three or more enemies fighting
--     you, Multi-Shot whenever it is ready. Reminds you of aspects (Viper when mana runs low, Hawk
--     again at half mana), pet care, Kill Command, major cooldowns on elites and bosses and
--     Silencing Shot. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay
--     with you.
[1756] = "1–70 级，所有专精。以猎人印记、瞄准射击和自动射击拉怪，保持自动射击，目标贴近时使用近战攻击。学会稳固射击之前，保持毒蛇钉刺，仅在法力充足时才把法力花在瞄准射击、多重射击和奥术射击上。62 级起：多重射击就绪即用，每次自动射击后立即使用稳固射击，用奥术射击填补空隙，单刷时使用毒蛇钉刺。有三个或更多敌人与你交战时，多重射击就绪即用。会提醒你守护（法力值不足时用蝰蛇守护，法力恢复到一半时换回雄鹰守护）、宠物照料、杀戮命令、对精英和首领使用主要冷却技能，以及沉默射击。宠物指令、误导、陷阱、乱射、近战穿插和假死由你自己掌控。",
-- 825c84d1 English: Ranged DPS (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Hunter,
--     The Burning Crusade Classic (variant key: Ranged / Wowhead). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1757] = "远程 DPS（Wowhead）",
-- c4d18a35 English: Levels 1–70, every spec, following Wowhead's raid advice. Same pull, melee,
--     leveling shots, multi-target Multi-Shot and reminders as the simulator version, but once
--     Steady Shot is learned it only offers Multi-Shot and Steady Shot after each Auto Shot: no
--     Arcane Shot filler (except while moving), no Serpent Sting and no Aspect of the Viper
--     reminder. Pet commands, Misdirection, traps, Volley, melee weaving and Feign Death stay with
--     you. An alternative to the recommended simulator ranged premade, off by default: enable it
--     and disable that one, or raise its priority.
[1758] = "1–70 级，所有专精，遵循 Wowhead 的团队建议。拉怪、近战、升级阶段的射击、多目标多重射击和提醒都与 模拟器 版本相同，但学会稳固射击后，每次自动射击后只提供多重射击和稳固射击：不用奥术射击填充（移动时除外），不用毒蛇钉刺，也没有蝰蛇守护提醒。宠物指令、误导、陷阱、乱射、近战穿插和假死由你自己掌控。它是推荐的 模拟器 远程内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。",
-- 4f534fae English: Melee DPS (simulator)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue, The
--     Burning Crusade Classic (variant key: DPS / simulator). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1759] = "近战 DPS（模拟器）",
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1760] = "1–70 级，所有专精。潜行时：预谋，然后单刷时偷袭、组队时锁喉，否则伏击（主手持匕首时）。战斗中：还击，两个连击点起使用切割（在最后两秒内续上），对即将死亡的目标使用刺骨，五个连击点时若割裂能持续足够久则使用割裂（剑刃乱舞顺劈期间除外），否则使用刺骨。目标没有攻击你时用毁伤或背刺（匕首）攒连击点，否则用出血或影袭。会提醒你缺少的毒药、脚踢、剑刃乱舞和冲动、冷血以及闪避。破甲、肾击、佯攻、消失和站位由你自己掌控。",
-- 5f9b3940 English: Melee DPS (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue, The
--     Burning Crusade Classic (variant key: DPS / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1761] = "近战 DPS（Wowhead）",
-- d6b11787 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the simulator version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended simulator melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[1762] = "1–70 级，所有专精，遵循 Wowhead。潜行起手、攒点技能和提醒与 模拟器 版本相同，但切割从一个连击点起就使用，每个五连击点终结技都是刺骨：不使用割裂。破甲、肾击、佯攻、消失和站位由你自己掌控。它是推荐的 模拟器 近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。",
-- d05e07b7 English: Balance
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid, The
--     Burning Crusade Classic (variant key: Balance).
[1763] = "平衡",
-- 8177cc43 English: Caster Balance from level 1 to 70, and the default for any Druid no other
--     premade fits. Pulls with Starfire (Wrath before 20), Insect Swarm and Moonfire while moving,
--     Faerie Fire in a group, Hurricane for three or more enemies, Moonfire when it has run out and
--     you have 30% mana, Starfire on Nature's Grace, Wrath against a target in melee, then Starfire
--     (Wrath before it is learned). No advice in Cat, Bear or travel forms. Reminders: Mark of the
--     Wild, Thorns while solo, Omen of Clarity, Moonkin Form, Force of Nature on a long fight,
--     Innervate when low.
[1764] = "施法型平衡，适用于 1 至 70 级，也是没有其他内置循环适用时所有德鲁伊的默认循环。以星火术拉怪（20 级前为愤怒），移动时使用虫群和月火术，组队时使用精灵之火，三个或更多敌人时使用飓风，月火术消失且你有 30% 法力值时补上月火术，自然之赐触发时使用星火术，对近战范围内的目标使用愤怒，然后是星火术（学会前为愤怒）。猎豹、熊或旅行形态下不提供建议。提醒：野性印记、单刷时的荆棘术、清晰预兆、枭兽形态、长时间战斗中的自然之力、法力值低时的激活。",
-- 9f5ae657 English: Feral (Icy Veins, Warcraft Tavern & simulator)
[1765] = "野性（Icy Veins、Warcraft Tavern & 模拟器）",
-- 43a0ca32 English: Cat and bear for the Feral tree, following your form. Cat: stealth opener
--     (Pounce, Ravage or Shred), Faerie Fire (Feral), Rip at four combo points on a target that
--     lives, Ferocious Bite between Rips without Clearcasting, Mangle kept up, Shred from behind or
--     Mangle/Claw when the target is on you. Bear: Faerie Fire, Lacerate saved before it drops,
--     Demoralizing Roar unless a warrior's Shout is up, Swipe for packs, Mangle, five Lacerates,
--     Swipe. In caster form it suggests Cat (or Bear) Form. Reminders: Mark, Thorns, Omen, Maul
--     with spare rage, Tiger's Fury before a pull, Frenzied Regeneration. Powershifting is an
--     optional step that starts off (it needs a powershift macro).
[1766] = "野性天赋树的猎豹和熊，跟随你当前的形态。猎豹：潜行起手（突袭、毁灭或撕碎），精灵之火（野性），对能存活的目标在四个连击点时使用撕扯，两次撕扯之间没有节能施法时使用凶猛撕咬，保持裂伤，在目标背后使用撕碎，目标正在攻击你时使用裂伤/爪击。熊：精灵之火，在割伤消失前续上，除非已有战士的挫志怒吼否则使用挫志咆哮，怪群使用横扫，然后裂伤、叠满五层割伤、横扫。人形态下会建议猎豹（或熊）形态。提醒：野性印记、荆棘术、清晰预兆、怒气有余时的重殴、拉怪前的猛虎之怒、狂暴回复。变身回能（powershifting）是默认关闭的可选步骤（需要一个变身回能宏）。",
-- 4c55a525 English: Feral (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid, The
--     Burning Crusade Classic (variant key: Feral / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1767] = "野性（Wowhead）",
-- 9092413a English: Wowhead's Feral, an alternative to the recommended Icy Veins Feral premade, off
--     by default: enable it and disable that one, or raise its priority. Rip whenever it is down at
--     four combo points and Ferocious Bite only on a target about to die (no bite-weaving); bears
--     spend free global cooldowns on Lacerate before Swipe. Innervate when a cat runs low on mana.
--     Otherwise the same as the Icy Veins variant.
[1768] = "Wowhead 的野性，是推荐的 Icy Veins 野性内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。撕扯不在时于四个连击点补上，凶猛撕咬仅用于即将死亡的目标（不穿插撕咬）；熊形态把空闲的公共冷却用在割伤上，再使用横扫。猎豹法力不足时使用激活。其余与 Icy Veins 版本相同。",
-- 6a3c6c77 English: Restoration
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Druid, The
--     Burning Crusade Classic (variant key: Restoration).
[1769] = "恢复",
-- da5557c1 English: Healing for the Restoration tree on your friendly target (or yourself): Healing
--     Touch after Nature's Swiftness, Swiftmend a dying target that has your Rejuvenation or
--     Regrowth, three rolling Lifeblooms in combat, Rejuvenation and Regrowth when missing, then
--     Regrowth in Tree of Life or Healing Touch outside it. A hostile target gets Moonfire and
--     Wrath for soloing. Reminders: Mark, Omen, Tree of Life, Nature's Swiftness, Tranquility,
--     Innervate and Rebirth. Choosing whom to heal and downranking stay with you.
[1770] = "恢复天赋树的治疗，作用于你的友方目标（或你自己）：自然迅捷后使用治疗之触，对带有你的回春术或愈合的濒死目标使用迅捷治愈，战斗中保持三层生命绽放滚动，缺少时补上回春术和愈合，然后在生命之树形态下使用愈合，不在该形态时使用治疗之触。目标为敌对时使用月火术和愤怒进行单刷。提醒：野性印记、清晰预兆、生命之树、自然迅捷、宁静、激活和复生。治疗谁以及降级施法由你自己掌控。",
-- 4f534fae English: Melee DPS (simulator)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warrior,
--     The Burning Crusade Classic (variant key: DPS / simulator). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1771] = "近战 DPS（模拟器）",
-- e30bf8c3 English: Levels 1–70, Arms or Fury. Charges to pull, then Victory Rush, Intercept,
--     Rampage, and Whirlwind when two or more enemies fight you (Thunder Clap before it is
--     learned). With Bloodthirst or Mortal Strike: that strike, Whirlwind with rage to spare,
--     Execute, Overpower. Before them: Whirlwind, Execute, Overpower, Rend. Spare rage goes to
--     Devastate or Sunder Armor, then Hamstring. Reminds you of Battle Shout, Bloodrage, Heroic
--     Strike or Cleave as rage dumps, Sweeping Strikes, Death Wish, Recklessness and interrupts.
--     Slam timing, stance dancing and Berserker Rage stay with you.
[1772] = "1–70 级，武器或狂怒。冲锋拉怪，然后是乘胜追击、拦截、暴怒，两个或更多敌人与你交战时使用旋风斩（学会前为雷霆一击）。拥有嗜血或致死打击时：使用该打击，怒气有余时旋风斩，斩杀，压制。学会它们之前：旋风斩、斩杀、压制、撕裂。多余的怒气用于毁灭打击或破甲攻击，然后是断筋。会提醒你战斗怒吼、血性狂暴、以英勇打击或顺劈斩消耗怒气、横扫攻击、死亡之愿、鲁莽以及打断。猛击时机、姿态切换和狂暴之怒由你自己掌控。",
-- 6d10d944 English: Melee DPS (Icy Veins)
[1773] = "近战 DPS（Icy Veins）",
-- b57d248a English: Levels 1–70, Arms or Fury, following Icy Veins. Same pull, reminders and
--     leveling steps as the simulator version, but with Mortal Strike Execute comes first, with
--     Bloodthirst Execute comes right after it, Whirlwind follows without holding rage, and
--     Hamstring only near full rage. Slam timing, stance dancing and Berserker Rage stay with you.
--     An alternative to the recommended simulator melee DPS premade, off by default: enable it and
--     disable that one, or raise its priority.
[1774] = "1–70 级，武器或狂怒，遵循 Icy Veins。拉怪、提醒和升级步骤与 模拟器 版本相同，但有致死打击时斩杀排在最前，有嗜血时斩杀紧随其后，旋风斩接着使用且不保留怒气，断筋仅在怒气接近满时使用。猛击时机、姿态切换和狂暴之怒由你自己掌控。它是推荐的 模拟器 近战 DPS 内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。",
-- 871d5911 English: Tank (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warrior,
--     The Burning Crusade Classic (variant key: Protection / Wowhead). Names in parentheses (guide
--     or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1775] = "坦克（Wowhead）",
-- 91dfa1ce English: Levels 10–70, chosen while you are in Defensive Stance. Shield Slam, Revenge,
--     Thunder Clap and Demoralizing Shout kept up on elites and bosses, then Devastate or Sunder
--     Armor. On packs: Thunder Clap and Demoralizing Shout first. Reminds you of Shield Block (with
--     a shield equipped) against bosses and higher-level enemies, Heroic Strike or Cleave, Battle
--     Shout, Bloodrage, Shield Bash and emergency Last Stand and Shield Wall. Taunting and other
--     utility stay with you.
[1776] = "10–70 级，处于防御姿态时选用。盾牌猛击、复仇，对精英和首领保持雷霆一击和挫志怒吼，然后是毁灭打击或破甲攻击。怪群时：先雷霆一击和挫志怒吼。会提醒你对首领和高等级敌人使用盾牌格挡（需装备盾牌）、英勇打击或顺劈斩、战斗怒吼、血性狂暴、盾击，以及紧急时的破釜沉舟和盾墙。嘲讽和其他辅助技能由你自己掌控。",
-- ea76d926 English: Tank (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warrior,
--     The Burning Crusade Classic (variant key: Protection / IcyVeins). Names in parentheses (guide
--     or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1777] = "坦克（Icy Veins）",
-- aa141592 English: Levels 10–70, chosen while you are in Defensive Stance, following Icy Veins.
--     Shield Slam, Revenge, then Devastate or Sunder Armor, with Rend at the start of a fight until
--     Shield Slam is learned. On packs: Thunder Clap, and Demoralizing Shout against elites. Shield
--     Block is reminded whenever your target is attacking you and you carry a shield. Taunting and
--     other utility stay with you. An alternative to the recommended Wowhead tank premade, off by
--     default: enable it and disable that one, or raise its priority.
[1778] = "10–70 级，处于防御姿态时选用，遵循 Icy Veins。盾牌猛击、复仇，然后是毁灭打击或破甲攻击，学会盾牌猛击之前在战斗开始时使用撕裂。怪群时：雷霆一击，对精英使用挫志怒吼。只要目标正在攻击你且你装备了盾牌，就会提醒盾牌格挡。嘲讽和其他辅助技能由你自己掌控。它是推荐的 Wowhead 坦克内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。",
-- 3adec7ba English: Damage (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: DpsIcyVeins). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1779] = "伤害（Icy Veins）",
-- 9b0711bb English: Damage from level 1 to 70, used whenever the healer premade does not apply.
--     Smite and wand early, then Mind Blast, Shadow Word: Pain, Mind Flay, Shadowform, Vampiric
--     Touch and Shadow Word: Death as you learn them; DoTs before Mind Blast; a dying target is
--     wanded when solo. Holy and Discipline questers get Holy Fire and Smite. Reminders: Inner
--     Fire, Fortitude, racial buffs, Inner Focus, Shadowfiend. A Mind Flay past its first tick is
--     cut short for a ready Mind Blast, or Shadow Word: Death above half health. Shields and
--     healing stay with you.
[1780] = "1 至 70 级的伤害输出，只要治疗内置循环不适用就会使用。前期使用惩击和魔杖，然后随着学会依次加入心灵震爆、暗言术：痛、精神鞭笞、暗影形态、吸血鬼之触和暗言术：灭；心灵震爆之前先上持续伤害效果；单刷时对濒死目标使用魔杖。神圣和戒律的任务玩家使用神圣之火和惩击。提醒：心灵之火、真言术：韧、种族增益、心灵专注、暗影恶魔。精神鞭笞在第一跳之后，会为已就绪的心灵震爆而被提前打断，或在生命值高于一半时为暗言术：灭而被提前打断。护盾和治疗由你自己掌控。",
-- ce79d246 English: Damage (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: DpsWowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1781] = "伤害（Wowhead）",
-- fe006eaa English: Damage after Wowhead's guides, an alternative to the recommended Icy Veins
--     damage premade, off by default: enable it and disable that one, or raise its priority. Mind
--     Blast opens and goes before DoT refreshes, Vampiric Embrace only when your health drops, and
--     a dying target gets spells instead of the wand. Otherwise the same as the recommended
--     premade.
[1782] = "依据 Wowhead 指南的伤害输出，是推荐的 Icy Veins 伤害内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。以心灵震爆开怪，并优先于刷新持续伤害效果，仅在生命值下降时使用吸血鬼的拥抱，对濒死目标使用法术而非魔杖。其余与推荐的内置循环相同。",
-- d0f0e9e6 English: Healer (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: HealerWowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1783] = "治疗（Wowhead）",
-- d31781e0 English: Healing in a group when Holy or Discipline is your main talent tree. It advises
--     on the friendly unit you target; you choose whom to heal. Prayer of Mending before pulls and
--     whenever ready, Renew, Power Word: Shield in emergencies, dispels, Circle of Healing or
--     Prayer of Healing for group damage, Binding, Flash and Greater Heal, and Greater Heal rank 1
--     as a cheap top-up. With an enemy targeted it offers light damage.
[1784] = "神圣或戒律是你的主天赋树时的队伍治疗。它针对你选中的友方单位提供建议；治疗谁由你决定。拉怪前以及就绪时使用愈合祷言，恢复，紧急时使用真言术：盾，驱散，队伍受伤时使用治疗之环或治疗祷言，联结治疗、快速治疗和强效治疗术，并以 1 级强效治疗术作为低耗补血。选中敌人时会提供少量伤害技能。",
-- 45321807 English: Healer (Icy Veins)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Priest,
--     The Burning Crusade Classic (variant key: HealerIcyVeins). Names in parentheses (guide or
--     tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft
--     Tavern) are proper names and stay unchanged.
[1785] = "治疗（Icy Veins）",
-- e31d4277 English: Healing after Icy Veins' order: Shield, dispels, Binding Heal, Renew, Flash
--     Heal, Greater Heal (any rank), group heals, and Prayer of Mending last. You choose whom to
--     heal. An alternative to the recommended Wowhead healer premade, off by default: enable it and
--     disable that one, or raise its priority.
[1786] = "依据 Icy Veins 顺序的治疗：真言术：盾、驱散、联结治疗、恢复、快速治疗、强效治疗术（任意等级）、群体治疗，最后是愈合祷言。治疗谁由你决定。它是推荐的 Wowhead 治疗内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。",
-- 8283f17a English: All trees (Icy Veins)
[1787] = "所有天赋树（Icy Veins）",
-- da4da042 English: Every talent tree from level 1 to 70. Curse, then Unstable Affliction,
--     Immolate, Corruption and Siphon Life as learned, Shadow Bolt or Incinerate; Nightfall and
--     Backlash procs first; Seed, Hellfire and Shadowfury for three or more enemies. Solo it drains
--     when hurt, Life Taps, wands, and uses Drain Soul or a finisher on a dying target. Reminders:
--     Fel Armor, Demon Armor or Demon Skin, your demon, sacrifice, Soul Link, Amplify Curse and
--     Soulshatter. Fears and other curses stay with you.
[1788] = "1 至 70 级的所有天赋树。诅咒，然后随着学会依次加入痛苦无常、献祭、腐蚀术和生命虹吸，暗影箭或烧尽；夜幕和反冲触发优先；三个或更多敌人时使用腐蚀之种、地狱烈焰和暗影之怒。单刷时受伤会吸取生命，会使用生命分流和魔杖，并对濒死目标使用吸取灵魂或收尾法术。提醒：邪甲术、魔甲术或恶魔皮肤、你的恶魔、恶魔牺牲、灵魂链接、诅咒增幅和灵魂碎裂。恐惧和其他诅咒由你自己掌控。",
-- e3790b25 English: Drain-tank (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Warlock,
--     The Burning Crusade Classic (variant key: DpsWowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[1789] = "吸血坦（Wowhead）",
-- 522ed69f English: Warlock after Wowhead's guides, an alternative to the recommended Icy Veins
--     Warlock premade, off by default: enable it and disable that one, or raise its priority. Solo
--     it drain-tanks: Drain Life is the filler once your DoTs are up and Immolate and Siphon Life
--     are kept for elite mobs. In a group Immolate always goes on, after Corruption and Siphon
--     Life. Otherwise the same as the recommended premade.
[1790] = "依据 Wowhead 指南的术士，是推荐的 Icy Veins 术士内置循环的替代方案，默认关闭：启用它并禁用那个，或提高它的优先级。单刷时采用吸血坦打法：持续伤害效果都上齐后以吸取生命作为填充，献祭和生命虹吸留给精英怪。组队时总是施放献祭，排在腐蚀术和生命虹吸之后。其余与推荐的内置循环相同。",
-- a97bc1c7 English: Apply changes to this selected item list. Other settings keep their own Apply
--     action.
[1791] = "将更改应用到此所选物品列表。其他设置各自有其“应用”操作。",
-- 4cec1d75 English: Choose an item list before editing.
[1792] = "编辑前请先选择一个物品列表。",
-- 550c388b English: The item list changed elsewhere. Close and reopen it before applying.
[1793] = "物品列表已在别处更改。请关闭并重新打开后再应用。",
-- 67559dc7 English: Native settings page unavailable: %s
-- %s #1: %s #1: the internal key of the settings page, e.g. "profiles" (shown as-is)
[1794] = "原生设置页面不可用：%s",
-- 0f6314b0 English: The native rotation editor is unavailable.
[1795] = "原生循环编辑器不可用。",
-- 4850b174 English: Required
-- Context: Checkbox on a field card in the schema editor (and its help title): the field must be
--     filled in before the condition can run.
[1796] = "必填",
-- 9bcec068 English: Required field references need review. Apply keeps the displayed root
--     requirements.
[1797] = "必填字段的引用需要检查。“应用”会保留所显示的根级必填要求。",
-- c463dfb4 English: Required root fields must have a value before this condition can run. Rename,
--     reorder and duplicate keep this flag; removing the field removes its requirement. Moving it
--     into a nested structure makes it optional. Undo restores both. Callback code is unchanged.
[1798] = "根级必填字段必须有值，此条件才能运行。重命名、重新排序和复制都会保留此标记；移除字段会移除其必填要求。将其移入嵌套结构会使其变为可选。撤销会同时恢复两者。回调代码保持不变。",
-- 8b8cd45b English: Copy condition description
-- Context: Button in the condition editor: copies the plain-language description of the condition
--     to the clipboard (verb phrase).
[1799] = "复制条件描述",
-- b5739be0 English: This condition exceeds the supported editor limits.
[1800] = "此条件超出了编辑器支持的上限。",
-- df58aeb6 English: Proc Glow
-- Context: Effect type in the effect editor dropdown and Effects help: a glow in the style of the
--     game's spell-proc highlight.
[1801] = "触发发光",
-- dce1c179 English: Loop duration
-- Context: Help topic title and setting for the proc glow effect: how long one loop of the glow
--     animation lasts.
[1802] = "循环时长",
-- a4f0db33 English: Start burst
-- Context: Checkbox in the effect editor for the proc glow effect (and its help title): plays the
--     start burst animation when the glow begins.
[1803] = "开场爆发",
-- b89fd7fd English: Proc Glow is unavailable on this client; Pixel glow will be used.
[1804] = "此客户端不支持触发发光；将改用像素发光。",
-- 34ae0a26 English: Rotation data requires recovery: %s
