[2792] = "键被字符串化、值保持不变的新表。",
-- f1052f11 English: Newest-first health snapshots containing time, value and max. Falsy input
--     returns only zero without reading the clock.
[2793] = "以最新者在前的生命值快照，包含 time、value 和 max。为假值的输入只返回零，不会读取时钟。",
-- 7276d3c4 English: No return values. The destination array is modified in place.
[2794] = "没有返回值。目标数组会被原地修改。",
-- 69c24773 English: No return values. The supplied table is modified in place.
[2795] = "没有返回值。所提供的表会被原地修改。",
-- da87cc23 English: Nonempty class filename token to count; no class-token whitelist is applied.
[2796] = "要统计的非空职业文件名标识；不应用职业标识白名单。",
-- 3694f9ed English: Nonempty historical school key for resist/immune; unused for runner.
[2797] = "用于 resist/immune 的非空历史法术类型键；runner 不使用。",
-- 7ee44b6f English: Normalized bounded socket snapshot with slots and complete, or nil when the
--     query is unavailable.
[2798] = "规范化的有限插槽快照，包含 slots 和 complete；查询不可用时为 nil。",
-- 93ec5fb4 English: Normalized requested subject with finite timeRemaining or timeRemainingReason;
--     nil when the required row or subject is unavailable.
[2799] = "规范化的所请求主题，包含有限的 timeRemaining 或 timeRemainingReason；所需的行或主题不可用时为 nil。",
-- 7663ebe1 English: Number of entries visited.
[2800] = "遍历到的条目数量。",
-- 7f36a397 English: Number or string to inspect; other types do not match.
[2801] = "要检查的数字或字符串；其他类型不匹配。",
-- 4e6ddf17 English: Numeric widget supporting slider bounds, percent display and pending-edit
--     validation.
[2802] = "支持滑块范围、百分比显示和待处理编辑验证的数值控件。",
-- c8144d6f English: Observation kind: cast or channel. These use different native interruptibility
--     tuple positions.
[2803] = "观测种类：cast 或 channel。它们使用原生可打断元组中的不同位置。",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2804] = "观测、历史、工作量上限或运算的可用性原因。",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2805] = "为所需的生命值预测重新观测一次受保护的无参数 GetTime。要求结果可读且为有限数字；保留带符号和小数值，不额外加入单调、整数或非负的限制。不使用时钟缓存或额外的原生查询。",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2806] = "观测客户端以碎片形式报告的点数资源（熊猫人之谜的爆燃灰烬）。current 严格使用 UnitPower(unit,powerType,true)，maximum 严格使用 UnitPowerMax(unit,powerType,true)；结果除以暴雪的 MAX_POWER_PER_EMBER（10），因此 35 个碎片即为 3.5。仅限探测策略。缺失、失败、受限或格式错误的数据保持不可用；绝不回退到整单位查询。不会添加缓存。",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2807] = "在已知的客户端上观测可读的原始单位等级。可读且不存在的单位返回 exists=false；存在的单位要求 UnitLevel 为正的有限整数。未知的首领等级，以及缺失、失败、受限或格式错误的观测会返回 nil 及原因。这不使用有效等级或缩放后的等级。",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2808] = "在探测或受限策略客户端上观测所选单位的职责，不发出观察请求。已知单位不存在时返回 false。优先使用可调用的现代观察 API，仅当它不可调用时才回退到旧版；所选 API 失败时绝不会回退。要求专精 ID 为正的有限整数，并且只使用确切的单参数 GetSpecializationInfoByID 调用的第五个返回值（职责）。所需信息缺失、失败、受限或格式错误时为不可用；可读的非空未来职责字符串保持原样。",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2809] = "在探测或受限策略客户端上观测单位的施法或引导。已知不存在的单位或可读的非活动结果返回 active=false。活动记录包含 name，或在名称为机密时包含 nameReason（单位仍在施法），以及可独立获取的 remainingSeconds、durationSeconds、interruptible 和 spellID 字段；可选字段不可用时附带 remainingReason、durationReason、interruptibleReason 或 spellReason。存在性观测缺失、失败或受限时返回 nil 及原因。",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2810] = "在探测或受限策略客户端上，从原生 UnitCreatureType 的第二个返回值观测生物身份。先检查确切的 UnitExists(unit)；可读的 false 会直接返回 false，不需要也不调用生物元数据。存在的单位要求可读的有限数字 ID；未使用的本地化名称不影响可用性。带符号、小数、零以及未来的有限 ID 都会作为已知值保留。所需信息缺失、失败、为 nil、受限或格式错误时返回 nil 及原因。不会添加生物枚举、翻译标题比较或长期缓存。",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2811] = "在探测或受限策略客户端上，观测确切的所选单位是否死亡或处于灵魂状态，或是否对玩家友好。所需观测缺失、失败、受限或格式错误时为不可用。单位不存在时为不可用，而不是否定匹配，在 NOT 下同样如此。不会保留跨轮询的状态。",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2812] = "观测宠物是否确切存在，并可选地观测其经 GetUnitName 格式化的显示名称。仅查询存在性时从不需要名称数据。已知不存在时会跳过名称查询。仅在请求时，存在的宠物才需要可读的非空名称；所需观测缺失、失败、为 nil、受限或格式错误时返回 nil 及原因。显示辅助函数只以原有的单个宠物参数调用，不回退到 UnitName，也不推断动作条、生命值或技能状态。",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2813] = "为点数资源条件观测确切的所选单位是否存在，并可选地观测其职业文件名。已知不存在时返回 exists=false，不读取职业。存在的单位只在请求时需要 UnitClass 的第二个返回值；未使用的本地化名称和 ID 不影响可用性。所需观测缺失、失败、受限或格式错误时保持为不可用。这不会选择资源或缓存身份。",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2814] = "在受支持且可读的客户端上观测显式的法力值或当前的原始能量资源。资源身份从实时的 PowerType 枚举中选择；显式法力值绝不会回退到当前能量条。已知不存在时返回 exists=false；缺失、失败、受限或格式错误的观测会返回 nil 及原因。current 模式下的数量保留带符号的原生资源；显式法力值为非负。仅在需要时请求最大值；百分比的使用者必须要求最大值为正。",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2815] = "在已验证的巫妖王之怒、大地的裂变和熊猫人之谜客户端布局上观测雕文插槽。返回 slots 和 complete 标记。每个插槽在已知锁定或为空时为 active=false，被占用时为 active=true 并附带 spellID，不可用时 active 为 nil 并附带原因。未知布局和失败的数量查询会返回 nil 及原因。这不会比较物品名称，也不能证明物品与法术身份的确切对应。",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2816] = "在检查 UnitExists 后观测一个所使用的原生单位元数据字段：class 使用 UnitClass 的第二个返回值，creature 使用本地化的 UnitCreatureType 名称，classification 使用 UnitClassification。可读且不存在的单位返回 false，不查询元数据。未使用的元组字段不影响可用性；所需的值缺失、失败、为 nil、受限或格式错误时返回 nil 及原因。不会添加玩家职业、GUID、枚举或翻译推断。",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2817] = "观测一个当前的单位标记：combat 使用 UnitAffectingCombat，enemy 使用以 player 为第一个单位的 UnitIsEnemy，pvp 使用 UnitIsPVP。可读且不存在的单位返回 false，不查询该标记。所需观测缺失、失败、受限或格式错误时返回 nil 及原因。这会保留确切的所选单位，不推断友好、可攻击或其他单位状态。",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2818] = "使用只带单个索引参数的 GetRuneType 观测一个确切的原生符文栏位。要求类型可读且为正的有限整数；已知的未来数字类型与所选类型保持区分，死亡符文是一个确切的类型而不是通配符。缺失、失败、受限或格式错误的观测保持为不可用。不会添加职业、单位、数量或推断基础符文的查询。",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2819] = "观测一个独立的无参数玩家标记：stealthed 使用 IsStealthed，control 使用 HasFullControl，outdoors 使用 IsOutdoors。可读的 true 和 false 保留其含义。所需数据缺失、失败、为 nil、受限或格式错误时返回 nil 及原因。不会添加存在性、副本或技能可用性的推断。",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2820] = "观测一个受保护的无参数 IsInInstance 元组。所需的可读布尔成员值与类型字段无关：已知在副本外时直接返回，不解释未使用的类型；在副本内时返回可读的字符串类型，或在该次要字段不可用时返回 instanceTypeReason。检测是否在副本外的调用方只需要成员值；在副本内比较类型时必须检查次要原因。不会添加户外、区域或单位推断。",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2821] = "依次观测所选单位是否存在、是否与玩家敌对，然后观测玩家在该单位上的仇恨状态。已知不存在、非敌人以及成功读取到的 nil 仇恨状态返回 false，以保留“无仇恨”判断。包括零在内的有限状态数值保留其原有的比较含义。所需信息缺失、失败、为 nil、受限或格式错误时返回 nil 及原因。不会添加可攻击、死亡、战斗或载具的推断。",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2822] = "在受支持的客户端上观测可读的当前生命值，并可选地观测最大生命值。可读且不存在的单位返回 exists=false。缺失、失败、受限或格式错误的观测会返回 nil 及原因；它们不能证明单位不存在或得出生命值。",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2823] = "使用一次受保护的无参数 GetShapeshiftForm 调用观测玩家当前的形态。保留每个可读的有限数字结果，包括零、带符号和小数值；不会推断更严格的原生索引范围。缺失、失败、为 nil、受限或非有限的数据保持为不可用。不会添加形态数量、职业、法术 ID、单位或可选参数。",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2824] = "只从原生的第二个返回值观测有效属性。在探测或受限策略客户端上，先查询确切的 UnitExists(unit)，然后对选择器 1..5 查询 UnitStat(unit,stat)，或对选择器 6 查询 UnitArmor(unit)。已知不存在时返回 exists=false；所需信息缺失、失败、受限或非有限时返回 nil。保留有限的带符号、小数和零值；忽略所有未使用的元组字段。1..6 的路由是 RM 的选择器策略，而非原生值域的限制。",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2825] = "观测显式选择的 TBC 玩家连击点传输方式。current 只使用 GetComboPoints(player,target)；maximum 使用带原始选择器的 UnitPowerMax(player,powerType)。其他客户端系列在此不可用，必须使用其现有的点数能量观测器。保留可读的有限带符号、小数和零值。缺失、失败、受限或格式错误的数据保持为不可用；所选的连击点查询失败时绝不会回退到 UnitPower。这不会观测其他角色，也不会添加缓存。",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2826] = "在探测或受限策略客户端上，观测确切的旧版 GetTalentGroupRole(group) 点号调用的第一个职责结果。将可读的所选天赋组原样转发，包括将 nil 作为一个参数；不推断天赋组范围、不替换为其他 API，也不查询玩家单位。完整的旧版主要声明并未成立。职责数据缺失、失败、受限、为空或格式错误时为不可用；可读的非空未来字符串保持原样。",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2827] = "使用一次受保护的无参数点号调用，观测区域 PvP 分类的第一个结果。优先使用可调用的 C_PvP.GetZonePVPInfo，仅当现代 API 不可调用时才使用全局辅助函数。成功返回 nil 或没有返回值时，会产生一个已知的空记录；缺失、失败、受限或格式错误的观测保持为不可用。可读的空字符串和未来字符串保留其确切含义，未使用的返回字段不决定可用性。在现代 API 返回结果或失败后，绝不切换后端。",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2828] = "在受支持且可读的客户端上观测玩家当前的移动速度。这只针对 player 查询 GetUnitSpeed，不检测其他单位，也不重定向载具所有权。零表示静止；正的有限小数速度仍然有效。缺失、失败、受限或格式错误的观测会返回 nil 及原因。",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2829] = "在已识别的客户端系列上观测单位的存在性。将所选单位原样传给一次受保护的 UnitExists 调用。保留可读的 true 和 false；所需观测缺失、失败、受限、为 nil 或格式错误时返回 nil 及原因。不会添加身份、可见性、距离或战斗状态的查询。",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2830] = "使用确切的 UnitExists、UnitCanAttack 和 UnitIsDead 判断，观测玩家是否可以攻击一个未死亡的所选单位。已知不存在或可读的不可攻击结果会返回 false，不查询死亡状态。所需观测缺失、失败、受限或格式错误时返回 nil 及原因。这不检测灵魂状态、距离、敌对状态或技能可用性，也不重定向单位所有权。",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2831] = "观测到的职业文件名字符串；已知单位不存在时为 false，不可用时为 nil。",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2832] = "观测到的成员身份；不可用时为 nil。",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2833] = "仅限所选资源：target-combo 用于显式的 TBC 玩家后备，power 用于现有的所选单位传输方式。",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2834] = "在探测或受限策略客户端上观测确切的 UnitExists(unit)，然后仅对存在的单位观测 UnitGUID(unit)。已知不存在时为 false。存在的身份要求可读的非空 GUID；所需信息缺失、失败、格式错误或受限时为不可用。不会添加生命值、提供者或额外单位的观测。",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2835] = "class、creature 或 classification 之一；不支持其他元数据种类。",
-- f4dbfa56 English: One of combat, enemy or pvp; other flag kinds are not supported.
[2836] = "combat、enemy 或 pvp 之一；不支持其他标记种类。",
-- 6a9d3fdc English: One of stealthed, control or outdoors; no other predicate is invoked.
[2837] = "stealthed、control 或 outdoors 之一；不会调用其他判断。",
-- e7332ebe English: One rounded numeric result from the original formula.
[2838] = "来自原始公式的一个舍入后的数字结果。",
-- ffb1aba4 English: Optional collection of key values selecting entries; its own keys are ignored.
[2839] = "可选的键值集合，用于选择条目；其自身的键会被忽略。",
-- a4bd9302 English: Optional ordering callback called as order(t, leftKey, rightKey).
[2840] = "可选的排序回调，以 order(t, leftKey, rightKey) 的形式调用。",
-- 3a0cafbd English: Optional positive class ID; nil queries the current player class under
--     protection.
[2841] = "可选的正数职业 ID；为 nil 时会在保护下查询当前玩家的职业。",
-- d8e2dd81 English: Original explicit readable finite nonnegative integer combo-resource selector,
--     including zero; retained for the maximum query.
[2842] = "原始的显式、可读、有限的非负整数连击资源选择器（包括零）；保留用于最大值查询。",
-- 8311cae8 English: Original non-nil lookup result, or a colored placeholder string.
[2843] = "原始的非 nil 查找结果，或一个带颜色的占位字符串。",
-- 32680ed5 English: Original non-nil value, or a colored placeholder string.
[2844] = "原始的非 nil 值，或一个带颜色的占位字符串。",
-- 80842131 English: Original rounded-age bucket count, omitted when the result is the lone zero.
[2845] = "原始的取整时长分段数；结果为单独的零时省略。",
-- 169b03f3 English: Packaged helper from Conditions/spatial.lua.
[2846] = "来自 Conditions/spatial.lua 的内置辅助函数。",
-- 18a2dc4d English: Packaged helper from utils.lua.
[2847] = "来自 utils.lua 的内置辅助函数。",
-- dd1476f6 English: Partial current/maximum record, empty when provider absent, or nil when
--     unavailable.
[2848] = "部分的当前值/最大值记录；提供者不存在时为空，不可用时为 nil。",
-- 52076b9c English: Partial record containing ready or readyReason, start or startReason, and
--     duration or durationReason; nil only when the query itself is unavailable.
[2849] = "部分记录，包含 ready 或 readyReason、start 或 startReason，以及 duration 或 durationReason；仅当查询本身不可用时为 nil。",
-- 7001225d English: Pet observation with Boolean exists and, for a requested present pet, name; nil
--     when required data is unavailable.
[2850] = "宠物观测，包含布尔值 exists，对于请求的存在的宠物还包含 name；所需数据不可用时为 nil。",
-- f4bb093a English: Policy or availability reason for a nil movement observation.
[2851] = "移动观测为 nil 时的策略或可用性原因。",
-- 7f7f12b8 English: Policy, capability or clock observation availability reason for a nil time.
[2852] = "时间为 nil 时的策略、能力或时钟观测可用性原因。",
-- 43794680 English: Policy, capability or required-observation availability reason.
[2853] = "策略、能力或所需观测的可用性原因。",
-- d35012ad English: Policy, query, capability or required row/subject availability reason for a nil
--     record.
[2854] = "记录为 nil 时的策略、查询、能力或所需行/主题的可用性原因。",
-- 59cf373b English: Policy, query-validation or availability reason for a nil metadata observation.
[2855] = "元数据观测为 nil 时的策略、查询验证或可用性原因。",
-- 5f9416e7 English: Policy, query-validation or availability reason for a nil pet observation.
[2856] = "宠物观测为 nil 时的策略、查询验证或可用性原因。",
-- 046d5773 English: Policy, query-validation or availability reason for a nil player flag.
[2857] = "玩家标记为 nil 时的策略、查询验证或可用性原因。",
-- a9338066 English: Policy, query-validation or availability reason for a nil quantity.
[2858] = "数量为 nil 时的策略、查询验证或可用性原因。",
-- bde90d0c English: Policy, query-validation or availability reason for a nil resource observation.
[2859] = "资源观测为 nil 时的策略、查询验证或可用性原因。",
-- cd1d6bc4 English: Policy, query-validation or availability reason for a nil threat observation.
[2860] = "仇恨观测为 nil 时的策略、查询验证或可用性原因。",
-- b963fb2b English: Policy, query-validation or availability reason for a nil unit flag.
[2861] = "单位标记为 nil 时的策略、查询验证或可用性原因。",
-- de3eca9c English: Policy, query-validation or availability reason for nil attackability.
[2862] = "可攻击性为 nil 时的策略、查询验证或可用性原因。",
-- e1be06fc English: Policy, query-validation or identity/selector availability reason for a nil
--     selector.
[2863] = "选择器为 nil 时的策略、查询验证或身份/选择器可用性原因。",
-- a82bb017 English: Policy, query-validation or required observation availability reason for a nil
--     quantity.
[2864] = "数量为 nil 时的策略、查询验证或所需观测的可用性原因。",
-- 3422d50e English: Policy, query-validation or required observation availability reason for a nil
--     record.
[2865] = "记录为 nil 时的策略、查询验证或所需观测的可用性原因。",
-- 6d8971dd English: Policy, query-validation or required-observation availability reason for a nil
--     ID.
[2866] = "ID 为 nil 时的策略、查询验证或所需观测的可用性原因。",
-- abb38505 English: Policy, query-validation or required-observation availability reason for a nil
--     match.
[2867] = "匹配结果为 nil 时的策略、查询验证或所需观测的可用性原因。",
-- 4be03f57 English: Policy, slot-validation or required observation availability reason for a nil
--     type.
[2868] = "类型为 nil 时的策略、栏位验证或所需观测的可用性原因。",
-- 07a2f2a4 English: Policy, slot-validation, capability or native-call availability reason for a
--     nil record.
[2869] = "记录为 nil 时的策略、栏位验证、能力或原生调用的可用性原因。",
-- 57d4e2a6 English: Policy, snapshot, identity or threat observation availability reason.
[2870] = "策略、快照、身份或仇恨观测的可用性原因。",
-- 88172c69 English: Policy, token-validation or availability reason for a nil identity result.
[2871] = "身份结果为 nil 时的策略、标识验证或可用性原因。",
-- 41f7dc66 English: Policy, validation or availability reason for a nil health observation.
[2872] = "生命值观测为 nil 时的策略、验证或可用性原因。",
-- cc67968e English: Policy, validation or availability reason for a nil snapshot.
[2873] = "快照为 nil 时的策略、验证或可用性原因。",
-- 84bacc88 English: Policy, validation or observation availability reason.
[2874] = "策略、验证或观测的可用性原因。",
-- 702b5d1d English: Policy, validation or required observation availability reason.
[2875] = "策略、验证或所需观测的可用性原因。",
-- e3a0a3ce English: Positive integer glyph item ID stored by the condition; arrays, item-set keys
--     and spell IDs are not item references.
[2876] = "条件中存储的正整数雕文物品 ID；数组、物品组键和法术 ID 不是物品引用。",
-- c7e5f035 English: Positive integer level, false for a known absent unit, or nil when unavailable.
[2877] = "正整数等级；已知单位不存在时为 false，不可用时为 nil。",
-- 2ce665d6 English: Positive integer spell ID, not a spell-book slot.
[2878] = "正整数法术 ID，而不是法术书栏位。",
-- 37be242f English: Positive item ID or native-recognized item name/link to classify.
[2879] = "要分类的正数物品 ID，或原生可识别的物品名称/链接。",
-- eac23024 English: Predicate that validates the proposed spell value.
[2880] = "验证拟议法术值的判断函数。",
-- b7acadb2 English: Present GUID, false for known absence, or nil when unavailable.
[2881] = "存在时为 GUID；已知不存在时为 false，不可用时为 nil。",
-- 5825055c English: Provider, validation or observation availability reason.
[2882] = "提供者、验证或观测的可用性原因。",
-- e78c7309 English: Query, policy or observation availability reason.
[2883] = "查询、策略或观测的可用性原因。",
-- b79b336b English: RM comparison operator identifier; missing labels use the operator placeholder.
[2884] = "RM 比较运算符标识符；缺失的标签使用运算符占位符。",
-- 505c9dde English: RM operator identifier.
[2885] = "RM 运算符标识符。",
-- a3bcccb3 English: Range record with applicable and, when applicable, inRange; nil when
--     unavailable.
[2886] = "距离记录，包含 applicable，适用时还包含 inRange；不可用时为 nil。",
-- a18d0c99 English: Read a fresh protected UnitClass player observation for rotation ownership.
--     Consume only the readable nonempty class filename from return two. No existence, level,
--     vehicle, family or combat-policy read is added, and no result persists across calls. Core
--     ownership still validates the class token and character key separately; overridden context
--     providers retain their complete original path.
[2887] = "为循环所有权读取一次全新的受保护 UnitClass 玩家观测。只使用第二个返回值中可读的非空职业文件名。不会添加存在性、等级、载具、客户端系列或战斗策略的读取，结果也不会跨调用保留。核心所有权仍会分别验证职业标识和角色键；被覆盖的上下文提供者保留其完整的原有路径。",
-- 97b3a051 English: Read a fresh protected zero-argument GetTime for rune cooldown arithmetic.
--     Require a readable finite number. This observation is deliberately uncached; callers preserve
--     the original clock-before-scan order and require its value only when a matching rune needs
--     timing. No evaluation-start substitution or inferred time is supplied.
[2888] = "为符文冷却运算读取一次全新的受保护无参数 GetTime。要求结果可读且为有限数字。此观测刻意不缓存；调用方保留原有的“先读时钟再扫描”顺序，并且只在有匹配的符文需要计时时才要求其值。不会以评估开始时间替代或推断时间。",
-- 3b2652a8 English: Read a lazy health scalar after a separate identity gate. Kind current uses
--     exact UnitHealth(unit); maximum uses exact UnitHealthMax(unit). Probe- and restricted-policy
--     clients accept readable finite nonnegative numbers including zero. No repeated existence/GUID
--     call or alternate tuple fallback is added.
[2889] = "在单独的身份检查之后读取惰性的生命值标量。current 种类使用确切的 UnitHealth(unit)；maximum 使用确切的 UnitHealthMax(unit)。探测或受限策略客户端接受可读的有限非负数字（包括零）。不会重复调用存在性/GUID 查询，也不会回退到其他元组。",
-- cd858e26 English: Read a normalized charge record: currentCharges, maxCharges, cooldownStartTime,
--     cooldownDuration, chargeModRate and isActive. Unsupported spells or restricted client data
--     return nil with a reason.
[2890] = "读取规范化的充能记录：currentCharges、maxCharges、cooldownStartTime、cooldownDuration、chargeModRate 和 isActive。不受支持的法术或受限的客户端数据会返回 nil 及原因。",
-- 3ba4fbdf English: Read a specified unit membership in the player party or raid. True raidOnly
--     queries only UnitInRaid; otherwise a true UnitInParty result short-circuits, false proceeds
--     to UnitInRaid, and unknown remains unavailable. Readable nil raid index means false; integer
--     raid index1..40 means true. Names are passed unchanged to native APIs; native name-query
--     acceptance requires client qualification.
[2891] = "读取指定单位是否属于玩家的小队或团队。raidOnly 为 true 时只查询 UnitInRaid；否则 UnitInParty 结果为 true 时直接返回，为 false 时继续查询 UnitInRaid，未知时保持为不可用。可读的 nil 团队索引表示 false；整数团队索引 1..40 表示 true。名称会原样传给原生 API；原生 API 是否接受名称查询需视客户端而定。",
-- 3db7feb7 English: Read and normalize a spell cooldown across supported clients. The returned
--     record contains startTime, duration, isEnabled and modRate. The timestamps and duration
--     already describe expiration in GetTime() seconds; do not divide them by modRate. When the
--     client hides the times (Retail and Forever in combat) the record is nil with reason
--     restricted-value, followed by the never-secret isEnabled, isActive and isOnGCD flags when
--     they can be read.
[2892] = "读取各受支持客户端的法术冷却并将其规范化。返回的记录包含 startTime、duration、isEnabled 和 modRate。时间戳和持续时间已经以 GetTime() 秒数描述到期时间；不要再除以 modRate。当客户端隐藏时间时（正式服和永久服的战斗中），记录为 nil，原因为 restricted-value，在可以读取时其后会附上永不为机密的 isEnabled、isActive 和 isOnGCD 标志。",
-- 4ae0aa42 English: Read normalized native item classification metadata. The record contains
--     canonical itemID, classID and subClassID, plus equipLoc, the non-localized INVTYPE_* equip
--     location token, when it is readable and nonempty; it does not require loaded item display
--     text. Missing, failed, malformed or restricted metadata returns nil with a reason.
[2893] = "读取规范化的原生物品分类元数据。记录包含规范的 itemID、classID 和 subClassID，以及在可读且非空时的 equipLoc（未本地化的 INVTYPE_* 装备位置标记）；不要求物品显示文本已加载。元数据缺失、失败、格式错误或受限时返回 nil 及原因。",
-- 5286a3fe English: Read one documented active loss-of-control row by its native index and
--     requested subject kind. Type queries require only the readable control type string; school
--     queries require only the readable finite nonnegative integer school mask. Optional timing is
--     returned as a finite timeRemaining or an explicit per-field reason, so an unrelated subject
--     does not require a usable timer. Missing rows are unavailable snapshot observations. No
--     display fields, inferred deadline, duration sum, maximum or native alias fallback is used.
[2894] = "按原生索引和所请求的主题种类，读取一条有文档的活跃失控记录行。type 查询只需要可读的控制类型字符串；school 查询只需要可读的有限非负整数法术类型掩码。可选的计时以有限的 timeRemaining 或逐字段的显式原因返回，因此不相关的主题不需要可用的计时器。缺失的行是不可用的快照观测。不会使用显示字段、推断的截止时间、持续时间总和、最大值或原生别名回退。",
-- 5a423c22 English: Read one explicitly selected point-resource quantity with an exact two-argument
--     UnitPower or UnitPowerMax query. The selector is required; no primary-resource inference or
--     actor remapping occurs. Preserve finite signed, fractional and zero quantities without
--     clamping. Missing, failed, restricted or nonfinite data remains unavailable. Current and
--     maximum are separate observations so callers can share current snapshots while requesting
--     maximum lazily.
[2895] = "使用确切的双参数 UnitPower 或 UnitPowerMax 查询，读取一个显式选择的点数资源数量。选择器为必需；不会推断主要资源或重新映射角色。保留有限的带符号、小数和零数量，不进行截断。缺失、失败、受限或非有限的数据保持为不可用。当前值和最大值是分开的观测，因此调用方可以共享当前值快照，同时按需延迟请求最大值。",
-- 9f37d74c English: Read one protected GetRuneCooldown tuple for an exact native slot. Normalize
--     ready, start and duration independently: ready requires a readable Boolean, while each time
--     requires a readable finite number and preserves signed, fractional and zero values. Every
--     unavailable field carries its own reason. A successful empty tuple yields a partial record;
--     missing capability, policy or native-call failure yields nil. Never infer ready from timing
--     or timing from ready. Cache this complete record at the caller to share one observation
--     between rune-count and cooldown predicates.
[2896] = "为一个确切的原生栏位读取一次受保护的 GetRuneCooldown 元组。分别规范化 ready、start 和 duration：ready 需要可读的布尔值，而每个时间值需要可读的有限数字，并保留带符号、小数和零值。每个不可用的字段都附带其自己的原因。成功返回空元组时会产生部分记录；缺少能力、策略或原生调用失败时返回 nil。绝不从计时推断 ready，也不从 ready 推断计时。请在调用方缓存这份完整记录，以便在符文计数和冷却判断之间共享一次观测。",
-- 0ab0e9af English: Read optional MobInfo2 historical observations on probe- and restricted-policy
--     clients. Cache only exact selected-unit presence; UnitName result one, UnitLevel result one
--     and the three-argument MI2_GetMobData(name,level,unit) dot call stay fresh each invocation.
--     Known absent units and successful unrecorded nil or omitted history remain distinct from
--     unavailable native/provider facts. Preserve readable runner scalar truthiness, school signs
--     and missing-Hits default one. Positive resistance ratios must be finite; complete immunity
--     consumes finite Hits while partial immunity needs only its negative school observation. Never
--     infer native resistance or borrow old records.
[2897] = "在探测或受限策略客户端上读取可选的 MobInfo2 历史观测。只缓存确切的所选单位存在性；UnitName 的第一个结果、UnitLevel 的第一个结果以及三参数的 MI2_GetMobData(name,level,unit) 点号调用每次都会重新获取。已知不存在的单位，以及成功返回的未记录的 nil 或省略的历史，与不可用的原生/提供者信息保持区分。保留可读的 runner 标量真值、法术类型符号以及缺少 Hits 时默认为一。正的抗性比例必须有限；完全免疫会使用有限的 Hits，而部分免疫只需要其负值的法术类型观测。绝不推断原生抗性或借用旧记录。",
-- a27fc0e3 English: Read optional RealMobHealth using its exact one-argument dot call. Absent
--     nil/false namespace returns an empty record. Normalize current and maximum independently:
--     nil/false fields permit native fallback, numeric zero remains present. Malformed, failed,
--     restricted, negative or nonfinite consumed provider facts are unavailable. No provider or
--     stale fallback cache is used.
[2898] = "使用确切的单参数点号调用读取可选的 RealMobHealth。命名空间不存在（nil/false）时返回空记录。分别规范化当前值和最大值：nil/false 字段允许回退到原生值，数字零仍视为存在。所使用的提供者信息格式错误、失败、受限、为负或非有限时为不可用。不使用提供者或过期的后备缓存。",
-- 0a7395cc English: Read public group membership on identified client families. Unknown clients are
--     unsupported. True raidOnly checks IsInRaid; false or nil checks IsInGroup using its native
--     default group category. A readable false result stays false. Missing, failed, malformed or
--     restricted observations return nil with a reason.
[2899] = "在已识别的客户端系列上读取公开的队伍成员身份。未知客户端不受支持。raidOnly 为 true 时检查 IsInRaid；为 false 或 nil 时使用原生默认的队伍类别检查 IsInGroup。可读的 false 结果保持为 false。缺失、失败、格式错误或受限的观测会返回 nil 及原因。",
-- 4a264ad3 English: Read public roster identity on identified client families. Input routing is
--     limited to player, party1 through party4 and raid1 through raid40. Call UnitExists with that
--     exact one-argument token first; known false returns false without querying class. For a
--     present unit, consume only UnitClass return two as a readable nonempty class filename string,
--     without a class enum restriction. Missing, failed, malformed or restricted required facts
--     return nil with a reason.
[2900] = "在已识别的客户端系列上读取公开的名单身份。输入路由仅限 player、party1 到 party4，以及 raid1 到 raid40。先以该确切的单参数标识调用 UnitExists；已知为 false 时直接返回 false，不查询职业。对于存在的单位，只使用 UnitClass 的第二个返回值作为可读的非空职业文件名字符串，不限制职业枚举。所需信息缺失、失败、格式错误或受限时返回 nil 及原因。",
-- 1f3c0a57 English: Read spell-specific range for a unit using the appropriate client API or
--     spell-book slot. A spell without a range restriction returns applicable=false; otherwise
--     applicable=true and inRange records whether the unit is in range. Unknown or inaccessible
--     observations return nil with a reason.
[2901] = "使用适当的客户端 API 或法术书栏位，读取某个单位针对特定法术的距离。没有距离限制的法术返回 applicable=false；否则 applicable=true，inRange 记录该单位是否在距离内。未知或无法访问的观测会返回 nil 及原因。",
-- d3d07abb English: Read the current positive nameplate visibility distance using the supported
--     CVar API. This limits a Distance Count query; it does not prove that all nearby units have
--     been observed. Missing, malformed, restricted or failed observations return nil with a
--     reason.
[2902] = "使用受支持的 CVar API 读取当前正的姓名板可见距离。这会限制“距离内计数”查询；它不能证明所有附近的单位都已被观测到。缺失、格式错误、受限或失败的观测会返回 nil 及原因。",
-- f4bc8da4 English: Read the documented active loss-of-control count with a protected zero-argument
--     dot call. Require a readable finite nonnegative integer. Zero is a complete empty scan and
--     does not require a row API. RM limits a scan to 256 rows and returns unavailable beyond that
--     resource budget; this is not a declared native maximum. Required missing, failed, restricted
--     or malformed observations remain unavailable.
[2903] = "使用受保护的无参数点号调用，读取有文档的活跃失控数量。要求结果可读且为有限的非负整数。零表示一次完整的空扫描，不需要行 API。RM 将扫描限制为 256 行，超出该资源预算时返回不可用；这并不是原生声明的最大值。所需观测缺失、失败、受限或格式错误时保持为不可用。",
-- 597a72b9 English: Read the player auto-repeat state for a spell such as Shoot or Auto Shot. This
--     is distinct from a current or queued cast. Modern clients receive the exact spell ID; a
--     legacy query resolves the player spell-book slot first. Restricted client policies,
--     unreadable results and unavailable book slots return nil with a reason. This observes state
--     and never starts or stops a spell.
[2904] = "读取玩家某个法术（例如射击或自动射击）的自动重复状态。这与当前或排队中的施法不同。现代客户端会收到确切的法术 ID；旧版查询会先解析玩家的法术书栏位。受限的客户端策略、无法读取的结果以及不可用的法术书栏位会返回 nil 及原因。这只观测状态，从不开始或停止法术。",
-- 89759fd9 English: Read the public LibRangeCheck interval for a unit. A successful upper bound is
--     inclusive; a positive failed lower bound is strict. A zero lower floor is synthetic. Neither
--     bound is an exact distance, and a missing upper bound is not proof that the unit is outside
--     every radius. Unavailable, malformed, restricted or failed observations return nil with a
--     reason.
[2905] = "读取某个单位的公开 LibRangeCheck 距离区间。成功的上限是包含的；正的失败下限是严格的。零下限是合成的。两个边界都不是精确距离，缺少上限也不能证明该单位在所有半径之外。不可用、格式错误、受限或失败的观测会返回 nil 及原因。",
-- 41e0213a English: Readability authority for consumed values.
[2906] = "所使用值的可读性判定依据。",
-- 7f7e5283 English: Readable canonical item classification record (itemID, classID, subClassID and
--     optional equipLoc), or nil when unavailable.
[2907] = "可读的规范物品分类记录（itemID、classID、subClassID 和可选的 equipLoc），不可用时为 nil。",
-- 708f11a6 English: Readable canonical itemID/classID/subClassID record when the item is a glyph
--     for the requested class; nil for invalid or unavailable metadata.
[2908] = "当物品是所请求职业的雕文时，返回可读的规范 itemID/classID/subClassID 记录；元数据无效或不可用时为 nil。",
-- b7b27422 English: Readable charge record, or nil when unavailable.
[2909] = "可读的充能记录；不可用时为 nil。",
-- 5274b7b7 English: Readable consumed metadata string, false for a known absent unit, or nil when
--     required data is unavailable.
[2910] = "可读的所使用元数据字符串；已知单位不存在时为 false，所需数据不可用时为 nil。",
-- 041c7f05 English: Readable cooldown record, or nil when unavailable.
[2911] = "可读的冷却记录；不可用时为 nil。",
-- c171ab16 English: Readable current state, or nil when unavailable.
[2912] = "可读的当前状态；不可用时为 nil。",
-- ea709ff8 English: Readable finite current-form observation, including zero for the current
--     unshifted comparison; nil when unavailable.
[2913] = "可读的有限当前形态观测，包括与当前未变形状态比较时的零；不可用时为 nil。",
-- 5fe2cef3 English: Readable finite positive integral rune type, or nil when unavailable.
[2914] = "可读的有限正整数符文类型；不可用时为 nil。",
-- 243ee644 English: Readable interval with optional minimum and maximum bounds in yards. At least
--     one bound is present; nil when unavailable.
[2915] = "可读的区间，带有可选的最小和最大边界（码）。至少存在一个边界；不可用时为 nil。",
-- 7c9763dd English: Readable nonempty selected unit token, passed unchanged as the single argument
--     to existence and creature metadata queries.
[2916] = "可读的非空所选单位标识，作为单个参数原样传给存在性和生物元数据查询。",
-- 2ce03ebb English: Readable nonempty unit token or native-recognized name, passed unchanged.
[2917] = "可读的非空单位标识或原生可识别的名称，原样传递。",
-- 30a14f21 English: Readable nonempty unit token to match, unchanged in the native observation.
[2918] = "要匹配的可读非空单位标识，在原生观测中保持不变。",
-- 4421ce67 English: Readable nonempty unit token, passed unchanged as the single native argument.
[2919] = "可读的非空单位标识，作为单个原生参数原样传递。",
-- 831ff884 English: Readable record with Boolean exists and the requested class filename when
--     present; nil when required data is unavailable.
[2920] = "可读记录，包含布尔值 exists，存在时还包含所请求的职业文件名；所需数据不可用时为 nil。",
-- e5d5a0bd English: Readable selected flag or nil when required data is unavailable.
[2921] = "可读的所选标记；所需数据不可用时为 nil。",
-- ae99174e English: Readable selected flag, false for a known absent unit, or nil when a required
--     observation is unavailable.
[2922] = "可读的所选标记；已知单位不存在时为 false，所需观测不可用时为 nil。",
-- 15d71981 English: Readable unit equality, false for a known absent first unit, or nil when
--     required observations are unavailable.
[2923] = "可读的单位相等结果；已知第一个单位不存在时为 false，所需观测不可用时为 nil。",
-- c72ce8bc English: Record with exists=false, or exists=true and finite value; nil when
--     unavailable.
[2924] = "记录为 exists=false，或 exists=true 并带有有限的 value；不可用时为 nil。",
-- bbdbf34c English: Record with exists=false; recorded=false for known no history; or runner,
--     ratio, or immune with hits/hitsReason. Nil means a required observation is unavailable.
[2925] = "记录为 exists=false；已知没有历史时为 recorded=false；或者为 runner、ratio 或 immune，并带有 hits/hitsReason。nil 表示所需观测不可用。",
-- d2443dc7 English: Record with inInstance and, when inside, instanceType or instanceTypeReason;
--     nil when membership is unavailable.
[2926] = "记录包含 inInstance，在副本内时还包含 instanceType 或 instanceTypeReason；成员值不可用时为 nil。",
-- b2c4007b English: Reference input kind, such as Spec_EditBox, used for spell suggestions.
[2927] = "用于法术建议的引用输入种类，例如 Spec_EditBox。",
-- 27542d97 English: Remove entries in place, preserving only keys listed among except values by
--     default. With invert true, remove listed keys and retain unlisted keys. Without an exception
--     list, the default removes every entry and invert true retains every entry. Nil input does
--     nothing.
[2928] = "原地移除条目，默认只保留 except 值中列出的键。invert 为 true 时，移除列出的键并保留未列出的键。没有例外列表时，默认会移除所有条目，而 invert 为 true 时会保留所有条目。输入为 nil 时不执行任何操作。",
-- e6ab096c English: Remove leading and trailing Lua-pattern whitespace from a string.
[2929] = "移除字符串开头和结尾符合 Lua 模式的空白字符。",
-- a3fc9f6e English: Resolve a readable raw unit level for condition evaluation. Known absence
--     returns false; unavailable observations return nil with a reason. Cache observations within
--     the supplied evaluation pass. Only valid player levels are retained between passes until a
--     skill, profile or level refresh.
[2930] = "为条件评估解析可读的原始单位等级。已知不存在时返回 false；观测不可用时返回 nil 及原因。在所提供的评估轮次内缓存观测。只有有效的玩家等级会在轮次之间保留，直到技能、配置文件或等级刷新。",
-- 1be3efe7 English: Resolve an exact cast-recipient name against the current bounded party or raid
--     roster, then observe membership through a unit token. Missing, ambiguous or changing roster
--     data remains unavailable; never reads the selected target or retains state across casts.
[2931] = "将确切的施法对象名称与当前有限的小队或团队名单进行匹配，然后通过单位标识观测其成员身份。名单数据缺失、含义不明确或正在变化时保持为不可用；绝不读取所选目标，也不在施法之间保留状态。",
-- bf87a408 English: Resolve point resources using the original live class mapping and identity
--     cache, with an explicit TBC player ComboPoints-fallback transport policy. A player fallback
--     matching the readable raw Enum.PowerType table and ComboPoints value captured at module load
--     selects target-combo; explicit class-map entries, other actors and other families retain
--     power. Replaced, inherited or unprovable fallback provenance retains power. This versioned
--     policy does not claim native UnitPower is broken or equivalent. Known unit absence returns
--     false; unavailable required observations return nil with a reason. No current or maximum
--     quantity is queried here.
[2932] = "使用原有的实时职业映射和身份缓存解析点数资源，并采用显式的 TBC 玩家 ComboPoints 后备传输策略。若玩家后备与模块加载时捕获的可读原始 Enum.PowerType 表和 ComboPoints 值相符，则选择 target-combo；显式的职业映射条目、其他角色和其他客户端系列保留 power。被替换、继承或无法证明来源的后备保留 power。此带版本的策略并不声称原生 UnitPower 有问题或与之等效。已知单位不存在时返回 false；所需观测不可用时返回 nil 及原因。此处不查询当前值或最大值。",
-- b9173e02 English: Resolve the selected unit point-resource selector using the live
--     class-to-resource map and ComboPoints fallback. Known absence returns false; unavailable
--     required identity or selector data returns nil with a reason. Share complete identity
--     observations within the evaluation pass. Only successful player class observations persist in
--     the current longterm cache, tied to the native UnitClass identity; existence is refreshed
--     each pass. This selects a resource without reading its current or maximum quantity.
[2933] = "使用实时的职业到资源映射和 ComboPoints 后备，解析所选单位的点数资源选择器。已知不存在时返回 false；所需的身份或选择器数据不可用时返回 nil 及原因。在评估轮次内共享完整的身份观测。只有成功的玩家职业观测会保留在当前的长期缓存中，并与原生 UnitClass 身份绑定；存在性在每个轮次都会刷新。这只选择资源，不读取其当前值或最大值。",
-- 718644e5 English: Resolve the spell identifier stored by a condition. With exact rank enabled the
--     supplied ID is retained; otherwise ranked Classic clients resolve the currently known rank
--     through the spell catalog. Returns nil and an availability reason if resolution cannot be
--     completed.
[2934] = "解析条件中存储的法术标识符。启用精确等级时会保留所提供的 ID；否则在有等级的经典版客户端上，会通过法术目录解析当前已知的等级。无法完成解析时返回 nil 和可用性原因。",
-- 1d0d55d1 English: Resolved spell ID, or nil when unavailable.
[2935] = "解析后的法术 ID；不可用时为 nil。",
-- 6ffafa71 English: Resolver mapping a typed spell name to its ID.
[2936] = "将输入的法术名称映射到其 ID 的解析器。",
-- 09cbb92e English: Return a present value unchanged, or a red display placeholder for nil. Use for
--     readable condition labels, not as a boolean fallback.
[2937] = "原样返回存在的值；为 nil 时返回红色的显示占位符。用于可读的条件标签，而不是作为布尔值的后备。",
-- d42a9ff5 English: Return the first key whose value equals the supplied value during pairs
--     traversal. Nil or false input tables and absent values return nil. Multiple matching keys
--     have no guaranteed selection order.
[2938] = "在 pairs 遍历过程中返回第一个值等于所提供值的键。输入表为 nil 或 false 以及值不存在时返回 nil。有多个匹配的键时，选择顺序不确定。",
-- 3f5f3e62 English: Right operand; DIVISIBLE requires a nonzero divisor.
[2939] = "右操作数；DIVISIBLE 要求除数不为零。",
-- 6734885b English: Rotation Master addon instance (implicit with colon calls).
[2940] = "Rotation Master 插件实例（使用冒号调用时隐含传入）。",
-- 46daa133 English: Rotation Master platform adapter (implicit with colon calls).
[2941] = "Rotation Master 平台适配器（使用冒号调用时隐含传入）。",
-- f0f9c415 English: Rotation Master platform adapter. A dot reference requires addon.Platform as
--     the first argument; a colon call supplies it implicitly.
[2942] = "Rotation Master 平台适配器。点号引用需要将 addon.Platform 作为第一个参数；冒号调用会隐含提供它。",
-- 3f1284ef English: Round with the existing floor(num * 10^places + 0.5) / 10^places formula.
--     Places defaults to zero and may be negative. Halfway negative values round toward positive
--     infinity; no finite-number validation or alternative rounding policy is added.
[2943] = "使用现有的 floor(num * 10^places + 0.5) / 10^places 公式进行舍入。places 默认为零，可以为负。处于一半的负值会向正无穷方向舍入；不会添加有限数字验证或其他舍入策略。",
-- 885bcca4 English: Run the historical health-snapshot trend formula using the live profile history
--     window, clock and legacy rounding service. Preserve its maximum-health transitions, early
--     stop at full or zero health, weighting, errors and return counts. An empty array, or
--     snapshots that record no weighted change, return only zero rather than a 0/0 result; this is
--     the legacy algorithm rather than a validated forecast.
[2944] = "使用实时配置文件的历史窗口、时钟和旧版舍入服务，运行历史生命值快照的趋势公式。保留其最大生命值的过渡、在满血或零血时提前停止、加权、错误和返回值数量。空数组或未记录任何加权变化的快照只返回零，而不是 0/0 的结果；这是旧版算法，而不是经过验证的预测。",
-- 472af904 English: Second exact unit token, passed unchanged to UnitIsUnit.
[2945] = "第二个确切的单位标识，原样传给 UnitIsUnit。",
-- 89bc8587 English: Second table to compare.
[2946] = "要比较的第二个表。",
-- 181d7eb2 English: Selected nonempty unit token, unchanged in native calls.
[2947] = "所选的非空单位标识，在原生调用中保持不变。",
-- ad96e1f2 English: Selected nonempty unit token, unchanged in native/provider calls.
[2948] = "所选的非空单位标识，在原生/提供者调用中保持不变。",
-- 0fe63d0e English: Selected nonempty unit token.
[2949] = "所选的非空单位标识。",
-- 2228fc20 English: Selected nonempty unit token; this call alone does not establish presence.
[2950] = "所选的非空单位标识；仅凭此调用不能确定其存在。",
-- f67a8632 English: Selected nonempty unit token; unchanged native argument.
[2951] = "所选的非空单位标识；作为原生参数保持不变。",
-- 9aeb1b04 English: Selected unit token forwarded as the only provider argument.
[2952] = "作为唯一的提供者参数转发的所选单位标识。",
-- 91d2e43e English: Selected unit token, unchanged in observations.
[2953] = "所选的单位标识，在观测中保持不变。",
-- 169d575d English: Selector widget supporting SetList, SetValue, SetLabel, SetDisabled and
--     callbacks.
[2954] = "支持 SetList、SetValue、SetLabel、SetDisabled 和回调的选择器控件。",
-- c4649a76 English: Shared evaluation cache; nil observes directly without a per-pass cache.
[2955] = "共享的评估缓存；为 nil 时直接观测，不使用每轮次的缓存。",
-- 32b53cb5 English: Source array whose ipairs prefix is inserted without copying nested values.
[2956] = "源数组，其 ipairs 前缀会被插入，嵌套的值不会被复制。",
-- f292d1c8 English: Specialization scope used to resolve spell suggestions.
[2957] = "用于解析法术建议的专精范围。",
-- 78f0e3c1 English: Spell ID or client-recognized spell name whose charges should be read.
[2958] = "要读取其充能的法术 ID 或客户端可识别的法术名称。",
-- 3b34f727 English: Spell ID or client-recognized spell name whose cooldown should be checked.
[2959] = "要检查其冷却的法术 ID 或客户端可识别的法术名称。",
-- 2d3ce2ab English: Spell ID or client-recognized spell name whose cooldown should be read.
[2960] = "要读取其冷却的法术 ID 或客户端可识别的法术名称。",
-- 55538bf5 English: Spell ID whose range should be checked.
[2961] = "要检查其距离的法术 ID。",
-- b7614a02 English: Spell field group containing an action icon, reference input and optional rank
--     control.
[2962] = "包含动作图标、引用输入框和可选等级控件的法术字段组。",
-- 31f8edf3 English: Spell-book scope: spell, pet or any.
[2963] = "法术书范围：spell、pet 或 any。",
-- 05372e4c English: Split a string into nonempty runs between separator characters. The separator
--     is inserted into a Lua pattern character class; it is not a literal multi-character
--     delimiter. Empty fields are omitted.
[2964] = "将字符串拆分为分隔字符之间的非空片段。分隔符会被插入到 Lua 模式的字符类中；它不是字面意义上的多字符分隔符。空字段会被省略。",
-- db7ca748 English: Stored spell ID to resolve.
[2965] = "要解析的已存储法术 ID。",
-- 9379f3fe English: Successful observation record with pvpType string or nil; nil record means
--     unavailable.
[2966] = "成功的观测记录，pvpType 为字符串或 nil；记录为 nil 表示不可用。",
-- e41b12b3 English: Table to copy shallowly, or nil.
[2967] = "要浅拷贝的表，或 nil。",
-- 07e8d4d0 English: Table to count, or nil for zero.
[2968] = "要计数的表；为 nil 时为零。",
-- 58e2d717 English: Table to inspect.
[2969] = "要检查的表。",
-- 90809a03 English: Table to modify, or nil to do nothing.
[2970] = "要修改的表；为 nil 时不执行任何操作。",
-- ff2b1485 English: Table to search; nil or false returns nil.
[2971] = "要搜索的表；为 nil 或 false 时返回 nil。",
-- 259ede57 English: Table to traverse; keys must be mutually comparable when no custom ordering is
--     supplied.
[2972] = "要遍历的表；未提供自定义排序时，键之间必须可以相互比较。",
-- f4e4becf English: Table whose keys should be converted to strings.
[2973] = "其键要被转换为字符串的表。",
-- a59c785e English: Table whose values must be mutually comparable.
[2974] = "其值之间必须可以相互比较的表。",
-- 2074ad97 English: Target line width, default 72 characters.
[2975] = "目标行宽，默认为 72 个字符。",
-- f3db5e09 English: Test a literal byte prefix using a Lua string slice. Empty prefixes match;
--     pattern characters have no special meaning and case is preserved.
[2976] = "使用 Lua 字符串切片测试字面的字节前缀。空前缀视为匹配；模式字符没有特殊含义，并区分大小写。",
-- 1f02a40c English: Test a literal byte suffix using a Lua string slice. Empty suffixes match;
--     pattern characters have no special meaning and case is preserved.
[2977] = "使用 Lua 字符串切片测试字面的字节后缀。空后缀视为匹配；模式字符没有特殊含义，并区分大小写。",
-- e2c64484 English: Text or number shown after the comparison wording.
[2978] = "显示在比较措辞之后的文本或数字。",
-- 026b376c English: Text or number shown before the comparison wording.
[2979] = "显示在比较措辞之前的文本或数字。",
-- b84e9fc7 English: Text to inspect.
[2980] = "要检查的文本。",
-- 95d67c5a English: Text to split.
[2981] = "要拆分的文本。",
-- a672408d English: Text to trim.
[2982] = "要修剪的文本。",
-- 332756da English: Text to wrap.
[2983] = "要换行的文本。",
-- 33010633 English: Text widget supporting label, text, pending-edit and callback methods.
[2984] = "支持标签、文本、待处理编辑和回调方法的文本控件。",
-- f6be6e89 English: Text with line breaks inserted at word boundaries.
[2985] = "在单词边界处插入换行的文本。",
-- 6f85c46a English: The selected value, including false or nil.
[2986] = "所选的值，包括 false 或 nil。",
-- 6af26a9c English: Transient trusted phrase recognized by condition summary rendering; do not
--     persist it as condition data.
[2987] = "条件摘要渲染所识别的临时可信短语；不要将其作为条件数据保存。",
-- 2bae0b3f English: Transient typed predicate used as a named phrase value; do not persist it as
--     condition data.
[2988] = "用作具名短语值的临时带类型判断；不要将其作为条件数据保存。",
-- 4cf99d8d English: Trimmed text.
[2989] = "修剪后的文本。",
-- e0249036 English: True also observes maximum health; false or nil reads current health only.
[2990] = "为 true 时还会观测最大生命值；为 false 或 nil 时只读取当前生命值。",
-- 9ba98a90 English: True also observes the selected resource maximum; false or nil reads current
--     quantity only.
[2991] = "为 true 时还会观测所选资源的最大值；为 false 或 nil 时只读取当前数量。",
-- 19d0b8a3 English: True also requires the present unit class filename; false reads existence only.
[2992] = "为 true 时还要求存在单位的职业文件名；为 false 时只读取存在性。",
-- ac4e613c English: True checks raid membership only; false or nil checks party or raid.
[2993] = "为 true 时只检查团队成员身份；为 false 或 nil 时检查小队或团队。",
