[2996] = "身份完全匹配时为 true；已知不存在或不匹配时为 false；所需数据或查询不可用时为 nil。",
-- 3286d546 English: True includes only listed entries; false or nil excludes listed entries.
[2997] = "为 true 时只包含列出的条目；为 false 或 nil 时排除列出的条目。",
